class Answer:
    def removeDuplicates(self, S):
        if not S:
            return S
        res = [S[0]]
        for curr in S[1:]:
            if res and curr == res[-1]:
                res.pop()
            else:
                res.append(curr)
        res = ''.join(res)
        return res

class Answer:
    def minAddToMakeValid(self, S):
        ans = bal = 0
        for symbol in S:
            bal += 1 if symbol == '(' else -1
            # It is guaranteed bal >= -1
            if bal == -1:
                ans += 1
                bal += 1
        return ans + bal

class Answer:
    def dailyTemperatures(self, T):
        n, right_max = len(T), float('-inf')
        res = [0] * n
        for i in range(n-1, -1, -1):
            t = T[i]
            if right_max <= t:
                right_max = t
            else:
                days = 1
                while T[i+days] <= t:
                    days += res[i+days]
                res[i] = days
        return res

class Answer:
    def scoreOfParentheses(self, S):
        ans = bal = 0
        for i, x in enumerate(S):
            if x == '(':
                bal += 1
            else:
                bal -= 1
                if S[i-1] == '(':
                    ans += 1 << bal
        return ans

class FreqStack:
    
    def __init__(self):
        self.freq = collections.Counter()
        self.group = collections.defaultdict(list)
        self.maxfreq = 0

    def push(self, x):
        f = self.freq[x] + 1
        self.freq[x] = f
        if f > self.maxfreq:
            self.maxfreq = f
        self.group[f].append(x)

    def pop(self):
        x = self.group[self.maxfreq].pop()
        self.freq[x] -= 1
        if not self.group[self.maxfreq]:
            self.maxfreq -= 1

        return x

class Answer:
    def selfDividingNumbers(self, left, right):        
        res = []

        for val in range(left, right+1):
            number = val
            isVal = True
            while number != 0:
                check = number%10
                if check == 0 or val%check != 0:
                    isVal = False
                    break
                number //= 10
            if isVal:
                res.append(val)

        return res

