class Answer:
    def rotateRight(self, head, k):

        if not head:
            return None

        if head.next == None:
            return head

        pointer = head
        length = 1

        while pointer.next:
            pointer = pointer.next
            length += 1

        rotateTimes = k%length

        if k == 0 or rotateTimes == 0:
            return head

        fastPointer = head
        slowPointer = head

        for a in range (rotateTimes):
            fastPointer = fastPointer.next


        while fastPointer.next:
            slowPointer = slowPointer.next
            fastPointer = fastPointer.next

        temp = slowPointer.next

        slowPointer.next = None
        fastPointer.next = head
        head = temp

        return head

class Answer:
    def mergeInBetween(self, list1, a, b, list2):

		ptr1 = list1
        ptr2 = list1
        i, j = 0, 0

        while i!=a-1:
            ptr1 = ptr1.next
            i += 1

        while j!=b:
            ptr2 = ptr2.next
            j += 1

        ptr1.next = list2

        while list2.next!=None:
            list2 = list2.next

        list2.next = ptr2.next

        return list1

class Answer:
    def swapNodes(self, head, k):

        slow, fast = head, head

        for _ in range(k - 1):
            fast = fast.next
        first = fast

        while fast.next:
            slow, fast = slow.next, fast.next

        first.val, slow.val = slow.val, first.val

        return head

