class Answer:
      def getIntersectionNode(self, headA, headB):
        nodes_in_B = set()
        while headB is not None:
            nodes_in_B.add(headB.val)
            headB = headB.next
        while headA is not None:
            if headA.val in nodes_in_B:
                return headA
            headA = headA.next
        return None

class Answer:
    def mergeInBetween(self, list1, a, b, list2):

        ptr1 = list1
        ptr2 = list1
        i, j = 0, 0

        while i!=a-1:
            ptr1 = ptr1.next
            i += 1

        while j!=b:
            ptr2 = ptr2.next
            j += 1

        ptr1.next = list2

        while list2.next!=None:
            list2 = list2.next

        list2.next = ptr2.next

