class FreqStack:
    def __init__(self):
        import collections
        self.freq = collections.Counter()
        self.group = collections.defaultdict(list)
        self.maxfreq = 0
    def push(self, x):
        f = self.freq[x] + 1
        self.freq[x] = f
        if f > self.maxfreq:
            self.maxfreq = f
        self.group[f].append(x)
    def pop(self):
        x = self.group[self.maxfreq].pop()
        self.freq[x] -= 1
        if not self.group[self.maxfreq]:
            self.maxfreq -= 1
        return x
    def get(self):
        return [item for sublist in self.group.values() for item in sublist]

