        self.freq[x] = f
        if f > self.maxfreq:
            self.maxfreq = f
        self.group[f].append(x)
    def pop(self):
        x = self.group[self.maxfreq].pop()
        self.freq[x] -= 1
        if not self.group[self.maxfreq]:
            self.maxfreq -= 1
        return x
    def get(self):
        return [item for sublist in self.group.values() for item in sublist]

class Answer:
    def selfDividingNumbers(self, left, right):

        res = []
        for val in range(left, right+1):

            number = val
            isVal = True

            while number != 0:
                check = number%10
                if check == 0 or val%check != 0:
                    isVal = False
                    break
                number //= 10
            if isVal:
                res.append(val)

        return res

