class Answer:
     def checkPossibility(self, nums):
            replace = 0
            n = nums

            for i in range(len(n)):
                if n != sorted(n) and replace < 2:
                    if i != len(n)-1:
                        if n[i] > n[i+1]:
                            n[i] = n[i+1]-1
                            replace += 1
                    else:
                        n[i] = n[i+1]-1
                        replace += 1

                elif n == sorted(n) and replace < 2:
                    return True
                    break
                else:
                    return False
                    break

class Answer:
    def minOperations(self, nums):
        count = 0
        prev = nums[0]
        for i in range(1, len(nums)):
            if nums[i] <= prev:
                count += (prev + 1 - nums[i])
                prev += 1
            else:
                prev = nums[i]
        return count

