        ptr1 = list1
        ptr2 = list1
        i, j = 0, 0

        while i!=a-1:
            ptr1 = ptr1.next
            i += 1

        while j!=b:
            ptr2 = ptr2.next
            j += 1

        ptr1.next = list2

        while list2.next!=None:
