class Answer:
    def sieve(self, n):      

        a = []
        for i in range(n + 1):
            a.append(i)

        a[1] = 0

        i = 2
        while i <= n:

            if a[i] != 0:

                j = i + i
                while j <= n:

                    a[j] = 0

                    j = j + i
            i += 1

        a = set(a)
        a.remove(0)

        return a

