class Answer:
    def twoSum(self, nums, target):
        seen = {}
        for i, v in enumerate(nums):
            remaining = target - v
            if remaining in seen:
                return [seen[remaining], i]
            seen[v] = i
        return []

class ListNode:
     def __init__(self, val=0, next=None):
         self.val = val
