    def calcMean(self, df1, df2, df3):
      df = pd.concat([df1, df2, df3], ignore_index=True)

      for i in df:
        df = df[df[i].notna()]

      df = df.reset_index(drop=True)
      df = df.append({'page1': df['page1'].mean(), 'page2': df['page2'].mean(), 
                'page3': df['page3'].mean()}, ignore_index=True)
