class Answer:
    def insertion_sort(self, nums):
      for i in range(1, len(nums)):
        t = nums[i]
        j = i -1
        while j >= 0 and t < nums[j]:
          nums[j+1] = nums[j]
          j = i - 1
         nums[j -1] = t
      return nums

class Answer:
    def insertion_sort(self, nums):
      for i in range(1, len(nums)):
        temp = nums[i]
        j = i - 1
        while (j >= 0 and temp < nums[j]):
            nums[j + 1] = nums[j]
            j = j - 1
        nums[j + 1] = temp

class Answer:
  def subtractProductAndSum(self, n):
    nums = []
    for i in str(n):
      nums.append(int(i))
      
    p, s = 1, 0
    
    for i in nums:
      p *= i
      s += i
      
    return p - s

