class Answer:
    def twoSum(self, nums, target):
        seen = {}
        for i, v in enumerate(nums):
            remaining = target - v
            if remaining in seen:
                return [seen[remaining], i]
            seen[v] = i
        return []

class Answer:
    def shuffle(self, nums, n):
        res = []
        for i, j in zip(nums[:n], nums[n:]):
            res += [i, j]
        return res

