    def __init__(self, filename):

        filetype = filename.rsplit(".", maxsplit = 1)[1]

        if filetype not in self.ALLOWED_TYPES:
            raise ValueError("Неправильное расширение")      

        self.type = filetype

  
    def printType(self):
        print(self.type)

  
    @staticmethod
    def describe():
        print('Вы можете вызвать этот метод без создания экземпляра класса')

