import re

class Answer:
    def validator(self, str):
        import re
        value = []
        items=[x for x in str.split(',')]
        for p in items:
            p = p.strip()
            if len(p) < 6 or len(p) > 12:
                continue
            else:
                pass
            if not re.search("[a-z]",p):
                continue
            elif not re.search("[0-9]",p):
                continue
            elif not re.search("[A-Z]",p):
                continue
            elif not re.search("[$#@]",p):
                continue
            else:
                pass
            value.append(p)
        return ", ".join(value)

import string
class Answer:
    @staticmethod
    def is_valid_password(password):
      length = 6 <= len(password) <= 12
      low_chr = any((i in string.ascii_lowercase for i in password))
      upp_chr = any((i in string.ascii_uppercase for i in password))
      dig = any((i in string.digits for i in password))
      sym = any((i in '$#@' for i in password))
      return all((length, low_chr, upp_chr, dig, sym))
  
    def validator(self, str):
      passwords = str.split(', ')
      filtered_passwords = filter(self.is_valid_password, passwords)
      return ', '.join(filtered_passwords)

def RepeatDecorator(func):
    ARGS = set()

    def wrapper(*args):
        if args in ARGS:
            print('Функция с такими аргументами уже запускалась!')
        else:
            ARGS.add(args)
        return func(*args)

    return wrapper

