class Answer:
    def bubble_sort(self, nums):
      nums = nums.copy()
      for i in range(len(nums)):
        for j in range(len(nums) - i):
          if nums[j - 1] > nums[j]:
            nums[j - 1], nums[j] = nums[j], nums[j - 1]
        return nums

