class Answer:
    def sieve(self, n):
        if n < 2:
            return []
        resheto = [*range(0, n + 1)]
        for p in range(2, n // 2 + 1):
            if resheto[p]:
                for i in range(p + p, n + 1, p):
                    resheto[i] = 0
        return [x for x in resheto if x][1:]

