class Answer:
    def minOperations(self, nums):
        total = 0
        for i in range(len(nums) - 1):
            if nums[i] >= nums[i + 1]:
                total += nums[i] - nums[i + 1] + 1
                nums[i + 1] = nums[i] + 1
        return total

