    def fizzbuzztest(self):
      initial = [x for x in range(1, 101)]
      result = []
      for x in initial:
        if x % 15 == 0:
          result.append('FizzBuzz')
        elif x % 3 == 0:
          result.append('Fizz')
        elif x % 5 == 0:
          result.append('Buzz')
        else:
          result.append(x)
      return result

