class Answer:
    def bubble_sort(self, nums):
        flag = False
        while not flag:
            flag = True
            for i in range(1, len(nums)):
                if nums[i - 1] > nums[i]:
                    nums[i - 1], nums[i] = nums[i], nums[i - 1]
                    flag = False
        return nums

class Answer:
    def selection_sort(self, nums):
        flag = False
        while not flag:
            flag = True
            for i in range(1, len(nums)):
                if nums[i - 1] > nums[i]:
                    nums[i - 1], nums[i] = nums[i], nums[i - 1]
                    flag = False
        return nums

