import re 

class Answer:
    @classmethod 
    def magic_dict(self, str):
        set1 = set(str)
        list1 = list(set1)
        list1.sort()
        magic_dict = {}
        for i in list1:
            if re.search(r'[a-zA-Z]', i) is None:
                continue
            magic_dict[i] = str.count(i)
        return magic_dict
      
      
