import time
class Answer:
    @classmethod
    def TimeDecorator(cls, func):
        def wrapper(*args, **kwargs):  
            start_time = time.time()
            result = func(*args, **kwargs)
            execution_time = time.time() - start_time
            print(f'Затрачено {execution_time} секунд')
            return result
        return wrapper  
      
      
@Answer.TimeDecorator  
def func2():
