class Answer:
    def checkPossibility(self, sequence):
           
        def incrementChecker(sequence): 
            counter = 0
            error = 0
            for index, value in enumerate(sequence[:-1]):
                if sequence[index+1] <= value:
                    counter+=1
                    error = index+1
    
            return(counter, error) 
    
        attempt = incrementChecker(sequence)    
        if attempt[0] > 1:
            return False
        elif len(sequence) - len(set(sequence)) > 1:
            return False
        else:
            new_seq = sequence[:attempt[1]]+sequence[(attempt[1]+1):]
            another_new_seq = sequence[:attempt[1]-1] + sequence[attempt[1]:]
            if incrementChecker(new_seq)[0] > 0 and incrementChecker(another_new_seq)[0] > 0:
                return False
        return True

