class Answer:
    def checkPossibility(self, nums):
        def check_num(nums_arr, iter_count=0):
            nums_offset = list([nums_arr[0]])
            nums_offset.extend(nums_arr)
            diff = [num - num_offset for num, num_offset in zip(nums_arr, nums_offset)]
            if len(nums_arr) <= 2 or (iter_count < 2 and all(x >= 0 for x in diff)):
                return True
            elif iter_count >= 2:
                return False
            for i, num_diff in enumerate(diff):
                if (num_diff < 0):
                    if (nums_arr[i-2] > nums_arr[i]) and (i > 1):
                        nums_arr[i] = nums_arr[i-1]
                    else:
                        nums_arr[i-1] = nums_arr[i]
                    iter_count += 1
                    return check_num(nums_arr, iter_count)
        return check_num(nums)

