class Answer:
    def checkPossibility(self, nums):    
        num_violations = 0
        for i in range(1, len(nums)):
            if nums[i - 1] > nums[i]:
                if num_violations == 1:
                    return False
                num_violations += 1
                if i < 2 or nums[i - 2] <= nums[i]:
                    nums[i - 1] = nums[i]
                else:
                    nums[i] = nums[i - 1]
        return True

class Answer:
    def checkPossibility(self, nums):
        if nums == sorted(nums):
            return False
        else:
            for e in range(len(nums) - 1):
                if nums[e] > nums[e + 1]:
                    n1 = nums.copy()
                    n1.pop(e+1)
                    err1 = n1 == sorted(n1)
                    n2 = nums.copy()
                    n2.pop(e)
                    err2 = n2 == sorted(n2)
                    return err1 or err2
        return True

