        cnt = 0
        if len(nums) in (1, 2):
            return True
        for i in range(1, len(nums)):
            if nums[i] < nums[i - 1]:
                nums[i] = nums[i - 1]
                cnt += 1
        if cnt <= 1:
            return True
        return False

class Answer:
    def jumpingOnClouds(self, clouds):
        # кол-во облаков
        n = len(clouds)
        # счетчик прыжков
        jumps = 0
        # счетчик облаков
        i = 0
        while i < n - 1:
            # если не можем прыгнуть через 2
            if i + 2 >= n or clouds[i + 2] == 1:
                i += 1
            else:
                i += 2
            jumps += 1
        return jumps

class Answer:
    def jumpingOnClouds(self, clouds):
        # если всего 1 облако
        if len(clouds) == 1 : return 0
        # если 2 облака
        if len(clouds) == 2: return 0 if clouds[1] == 1 else 1
        # если при перепрыгивании попадаем на тучу
        if clouds[2] == 1: 
            return 1 + jumpingOnClouds(clouds[1:])
        # если при перепрыгивании попадаем на облачко
        if clouds[2] == 0:
            return 1 + Answer().jumpingOnClouds(clouds[2:])

