class Answer:
    def checkPossibility(self, nums):
        cnt = 0
        if len(nums) == 1:
            return 'true'
        for i in range(len(nums) - 1):
            for j in range(i + 1, len(nums)):
                if nums[i] > nums[j]:
                    nums[i] = nums[j]
                    cnt += 1
        if cnt <= 1:
            return 'true'
        return 'false'

