class Answer:
    def jumpingOnClouds(self, clouds):
        # введите свой код ниже
        jumps = 0
        for i in range(0, len(clouds)):
            if clouds[i] == 0:
                jumps += 1
                k = i-1
                if clouds[i] == clouds[k] and k != -1:
                    jumps -= 1

        return jumps

class Answer:
    def removeDuplicates(self, s):
        len_s = -1
        while len_s != len(s):
            len_s = len(s)
            for char in set(s):
                s = s.replace(char * 2, '')
        return s

