class Answer:
    def checkPossibility(self, nums):
        num_violations = 0
        for i in range(1, len(nums)):
            if nums[i - 1] > nums[i]:
                if num_violations == 1:
                    return False
                num_violations += 1
                if i < 2 or nums[i - 2] <= nums[i]:
                    nums[i - 1] = nums[i]
                else:
                    nums[i] = nums[i - 1]
        return True

class Answer:
    def isValid(self, s):
        parameters_list = [
            dict(start='(', finish=')', state=0),
            dict(start='[', finish=']', state=0),
            dict(start='{', finish='}', state=0),
        ]

        for symbol in s:
            for parameters in parameters_list:
                if symbol in parameters['start']:
                    parameters['state'] += 1
                if symbol in parameters['finish']:
                    parameters['state'] -= 1
        
        for parameters in parameters_list:
            if parameters['state'] != 0:
                return False
        
        return True

