class Answer:
    def removeDuplicates(self, S):
        while self.has_duplicate(S):
            S = delete_duplicate(S)
            
        
    def has_duplicate(self, S):
        symbols_set = set(S)
        for symbol in symbols_set:
            if symbol*2 in S:
                return True
        return False
    
