class Answer:
    def scoreOfParentheses(self, S):
        stack = [0]

        for x in S:
            if x == '(':
                stack.append(0)
            else:
                v = stack.pop()
                stack[-1] += max(2 * v, 1)

        return stack.pop()

class Answer:
    def sieve(self, n):
        # Список простых чисел
    	prime_num = []
    	# Множество для вычеркивания чисел
    	sieve_num = set()

    	for i in range(2, n):

    		if i not in sieve_num:
    			prime_num.append(i)
    			# Вычеркиваем числа кратные i
    			sieve_num.update({n for n in range(i+i, n, i)})

    	return prime_num

