class Answer:
    def max_char(self, str1):
        sorted_str = sorted(str1)

        cur_letter = sorted_str[0]
        cur_count = 0

        max_letter = ''
        max_count = 0

        for let in sorted_str:
            if let == cur_letter:
                cur_count += 1
            else:
                cur_letter = let
                cur_count = 1

            if cur_count > max_count:
                max_count = cur_count
                max_letter = cur_letter

        return (max_letter, max_count)

