class Answer:
    def perms(self, arr): 
    	if len(arr) == 1:
    		return [(arr[0],)]
    	else:
    		result = []
    		for i in range(len(arr)):
    			cutarr = arr.copy()
    			del cutarr[i]
    			permutations = self.perms(self, cutarr)
    			result += [(arr[i],) + permutations[j] for j in range(len(permutations))]
    		return result

