class FreqStack:
    
    def __init__(self, lst=[]):
        self.lst = lst
    
    def push(self, n):
        return self.lst.append(n)
    
    def most_common_list(self):
        
        l = Counter(self.lst)
        
        most_common_list = [i[0] for i in l.most_common() if i[1] == max(l.values())]
        if len(most_common_list)>1:
            return most_common_list[-1]
        return most_common_list[0]
    
    def pop(self):
        
        to_remove = self.most_common_list()
        self.lst.reverse()
        self.lst.remove(to_remove)
        self.lst.reverse()
        return self.lst

