class Answer:
    def bubble_sort(self, nums):
        max_len = len(nums)
        for i in range(max_len - 1):
            rev = 0
            for j in range(max_len - i - 1):
                if nums[j] > nums[j + 1]:
                    nums[j], nums[j + 1] = nums[j + 1], nums[j]
                    rev = 1
            if rev == 0: return nums
        return nums

