        for index, _ in enumerate(A):
            lArray = [index:index+L]
            if len(lArray) != L:
                continue
            leftSlice = [:index]
            rightSlice = [index+L:]          
            for mArray in self.getM(leftSlice, rightSlice, M):
                currentSum = sum(lArray) + sum(mArray)
                maxSum = max(maxSum, currentSum)
