class Answer:
    def mergeTwoLists(self, a, b):
        if a and b:
            if a.val > b.val:
                a, b = b, a
            a.next = self.mergeTwoLists(a.next, b)
        return a or b

class Answer:
    def twoSum(self, nums, target):
        l = []
        result = []
        for x, y in combinations(nums, 2):
            if x + y == target:
                l.append(x)
                l.append(y)
        for idx, num in enumerate(nums):
            if num in l:
                result.append(idx)
        return result

