class Answer:
    def buildArray(self, target, n):
        l = np.arange(1,n+1).tolist()
        lst = iter(l)
        r = []
        while len(target)>0:
            i = next(lst)
            if i in target:
                r.append("Push")
                target.pop(target.index(i))
            else:
                r.append("Push")
                r.append("Pop")
        return r

