class Answer:
    def selection_sort(self, nums):
        max_len = len(nums)
        for i in range(max_len - 1):
            min = i
            for j in range(i + 1, max_len):
                if nums[j] < nums[min]:
                    min = j
            nums[i], nums[min] = nums[min], nums[i]
        return nums

