class Answer:
    def sieve(self, n): 

        if n is None or n <= 1:
            return None

        nums = set(range(2, n+1))
        p = 2
        done = False

        while not done:
            nums -= {x*p for x in range(p, n) if x*p <= n}
            if p <= max(nums)//2:
                nxt = next(x[0] for x in enumerate(nums) if x[1] > p)
                p = list(nums)[nxt]
            else:
                done = True

        return sorted(list(nums))

