class Answer:
    def sieve(self, n):
        if n is None or n <= 1:
            return []
        nums = set(range(2, n+1))
        result = []
        while nums:
            prime = min(nums)
            result.append(prime)
            nums -= set(range(prime, n+1, prime))
        return result

