class Answer:
    def scoreOfParentheses(self, S):
        if S == '' or S is None:
            return None

        dict = {'(': 1, ')': -1}
        nums = [dict[x] for x in S]
        ind = [i for i, x in enumerate(nums) if not sum(nums[:i+1])][0]+1
        result = 0

        if S[1:ind-1]:
            result += 2 * self.scoreOfParentheses(S[1:ind-1])
        else:
            result += 1

        if S[ind:]:
            result += self.scoreOfParentheses(S[ind:])

        return result

class Answer:
    def scoreOfParentheses(self, S):
        if S == '' or S is None:
            return None

        dict = {'(': 1, ')': -1}
        nums = [dict[x] for x in S]
        ind = [i for i, x in enumerate(nums) if not sum(nums[:i+1])][0] + 1

        first = S[1:ind-1]  # first detachable without ()
        second = S[ind:]    # the rest of S is untouched

        result = 2 * self.scoreOfParentheses(first) if first else 1
        result += self.scoreOfParentheses(second) if second else 0

        return result

