class Answer:
    def isValid(self, s):
        if s in ('', None):
            return None

        if s in ('()', '[]', '{}'):
            return True

        br_pair = {'(': ')', '[': ']', '{': '}'}

        if s[0] in br_pair:
            # 1 for an opening and -1 for a closing bracket
            br_nums = {s[0]: 1, br_pair[s[0]]: -1}
        else:
            return False

        nums = [br_nums.get(x, 0) for x in s]
        # 0 for any other type of bracket

        if sum(nums):  # check for the right pairs
            return False

        ind = [i for i, x in enumerate(nums) if not sum(nums[:i+1])][0]

        first = s[1:ind]    # first detachable without brackets
        second = s[ind+1:]  # the rest of S is untouched

        result = self.isValid(first) if first else True
        result &= self.isValid(second) if second else True

        return result

