class FreqStack:

    def __init__(self):
        self.obj = []
        self.dict = {}

    def push(self, value):
        key = int(value)

        if key not in self.dict:
            self.dict[key] = 1
        else:
            self.dict[key] += 1

        self.obj.append(key)

    def pop(self):
        if self.dict == {}:
            return None

        dic_items = list(self.dict.items())
        max_frq = max([x[1] for x in dic_items])

        part_obj = []

        while self.obj:
            pop_item = self.obj.pop()
            if self.dict[pop_item] == max_frq:
                self.dict[pop_item] -= 1
                self.obj += part_obj
                return pop_item
            else:
                part_obj = [pop_item, ] + part_obj

    def get(self):
        return self.obj

