                res.append("Pop")
            else:
                target.pop(0)

        return res

class FreqStack:
    def __init__(self):
        self._items = list()
    
    def push(self, value):
        self._items.append(value)
    
    def pop(self):
        meta = dict()
        for index, item in enumerate(self._items):
            meta.setdefault(item, dict(count=0, last_index=0))
            meta[item]['count'] += 1
            meta[item]['last_index'] = index
        
        max_item = max(meta, key=lambda item: item['count'])
        max_index = max_item['last_index']
        item = self._items.pop(max_index)
        return item
    
    def get():
        return self._items

