class Answer:
    def subtractProductAndSum(self, n):
        sum_of_figures = 0
        product_of_figures = 1
        
        while n:
            figure = n % 10
            n = n // 10
            sum_of_figures += figure
            product_of_figures *= figure
            
        return product_of_figures - sum_of_figures

