class Answer:
    def oddEvenList(self, head):
        if head is None or head.next is None:
            return head
        first, second = prev_even, prev_odd = head, head.next
        last_even, last_odd = None, None
        while head.next:
            head = head.next
            last_even = head
            prev_even.next = last_even
            if head.next:
                head = head.next
                last_odd = head
                prev_odd.next = last_odd
        if last_even:
            last_even.next = second
        else:
            prev_even.next = second

        if last_odd:
            last_odd.next = None
        else:
            prev_odd.next = None 
        return first

