class Answer:
    def checkPossibility(self, nums) -> bool:
        decreasing = 0
        
        for i in range(1, len(nums)):
            prev = nums[i - 1]
            current = nums[i]
            
            if current < prev:
                decreasing += 1
                if decreasing > 1:
                    return False
                
        return True
                

        
