class Answer:
    def quick_sort(self, nums):
        if len(nums) <= 1:
            return nums
        else:
            q = random.choice(nums)
            s_nums = []
            m_nums = []
            e_nums = []
            for n in nums:
                if n < q:
                    s_nums.append(n)
                elif n > q:
                    m_nums.append(n)
                else:
                    e_nums.append(n)
            return quicksort(s_nums) + e_nums + quicksort(m_nums)

class Answer:
    def quick_sort(self, nums):
        nums = []
        n = 1
        while n < len(nums):
               for i in range(len(nums) - n):
                 if nums[i] > nums[i + 1]:
                     nums[i], nums[i + 1] = nums[i + 1], nums[i]
                n += 1

