class Answer:
    def frequencySort(self, A):
        if A in ('', None):
            return A
        d = {}
        res = []
        for x in A:
            d[x] = d.get(x, 0) + 1
        for i in set(list(d.values())):
            subset = [y for y in A if d[y] == i]
            res += sorted(subset, reverse=True)
        return res

