        return KeyError

class Answer:
    def twoSum(self, nums, target):
        if nums is None or target is None:
            return ValueError
        for i in range(len(nums)):
            if nums[i] > target:
                continue
            for j in range(i+1, len(nums)+1):
                if int(nums[i]) + int(nums[j]) == target:
                    return sorted([i, j])
        return KeyError

