class Answer:
    def jumpingOnClouds(self, clouds):
        dl = len(clouds)
        jumps = 0
        cnt_cloud = 0
        while cnt_cloud < dl - 1:
            if cnt_cloud + 2 >= dl or clouds[cnt_cloud + 2] == 1:
                cnt_cloud += 1
            else:
                cnt_cloud += 2
            jumps += 1
        return jumps

