class Answer:
    def rotateRight(self, head, k):
        first, last = head, None
        k_prev, k_last = None, None
        i = 0

        while head:
            if i == k - 1:
                k_prev = head
                k_last = head.next
            i += 1
            if k_prev and k_last:
                k_prev = k_prev.next
                k_last = k_last.next
                        
            if head.next == None:
                last = head
            head = head.next
        
        last.next = first
        k_prev.next = None
        return k_last

