class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        sorted_array = sorted(arr)
        len_array = len(sorted_array)
        if len_array % 2 == 0:
            index_median = len_array // 2
            res = (sorted_array[index_median-1] + sorted_array[index_median]) / 2
        else:
            index_median = len_array // 2
            res = sorted_array[index_median]
        return res

