        elif len(a) % 2 == 0:
            a1 = a[int(len(a) / 2)]
            a2 = a[int(len(a) / 2 - 1)]
            res = (a1 + a2) / 2
        else:
            a1 = a[int((len(a) - 1) / 2)]
            res = a1
        return res

