class Answer:
    def PureIntersection(self, arr1, arr2):
        # введите свой код ниже
        res = []
        if len(arr1) >= len(arr2):
            for i in arr1:
                if i in arr2:
                    if i not in res:
                        res.append(i)
                    else:
                        continue
                else:
                    continue
        else:
            for i in arr2:
                if i in arr1:
                    if i not in res:
                        res.append(i)
                    else:
                        continue
                else:
                    continue
        return res

