class Answer:
    def gcd(self, a, b):  
        gcd = 0
        limit = min(a, b)
        for number in range(1, limit + 1):
            is_divisble_by_a = a % number == 0
            is_divisble_by_b = b % number == 0
            if is_divisble_by_a and is_divisble_by_b:
                gcd = number
        return gcd

