class Answer:
    def pairs(self, A, B):
        pairs = list()
        
        length = max(len(A), len(B))
        A = [*A, *[0] * (length - len(A))]
        B = [*B, *[0] * (length - len(B))]
        
        for number, line in zip(A, B):
            pairs.append(tuple(number, line))
    
        return pairs

