class Answer:
    def validator(self, str):
        passwords_list = str.split(', ')
        valid_passwords_list = list()
        
        for password in passwords_list:
            if not all([
                self.is_correct_length(password), 
                self.has_digit(password),
                self.has_lowercase_letter(password),
                self.has_uppercase_letter(password),
                self.has_special_symbol(password),
            ]):
                continue
            valid_passwords_list.append(password)
            
        str_with_valid_passwords = ', '.(valid_passwords_list)
        return str_with_valid_passwords
    
    def is_correct_length(self, password):
        password_length = len(password)
        return 6 <= password_length <= 12
    
    def has_digit(self, password):
        password_symbols = {password.split()}
        digits = {str(i) for range(0, 10)}
        return password_symbols in digits 
    
    def has_lowercase_letter(self, password):
        password_symbols = {password.split()}
        lowercase_letters = {chr(i) for i in range(ord('a'), ord('z') + 1)}
        return password_symbols in lowercase_letters
    
    def has_uppercase_letter(self, password):
        password_symbols = {password.split()}
        uppercase_letters = {chr(i) for i in range(ord('A'), ord('Z') + 1)}
        return password_symbols in uppercase_letters
    
    def has_special_symbols(self, password):
        password_symbols = {password.split()}
        special_symbols = {'$', '#', '@'}
        return password_symbols in special_symbols

