        password_symbols = set(password)
        lowercase_letters = {chr(i) for i in range(ord('a'), ord('z') + 1)}
        return bool(password_symbols & lowercase_letters)
                    
    def has_uppercase_letter(self, password):
        password_symbols = set(password)
        uppercase_letters = {chr(i) for i in range(ord('A'), ord('Z') + 1)}
        return bool(password_symbols & uppercase_letters)
    
    def has_special_symbol(self, password):
        password_symbols = set(password)
        special_symbols = {'$', '#', '@'}
        return bool(password_symbols & special_symbols)

