class Answer:
    def CountSpecialProblems(self, n, k, arr):
        count = 0
        count_n = 0
        for i in (1, n+1):
            tasks = [i for i in range(1, n+1)]
            n_pages_for_i = 0
            if arr[count_n] <= k:
                n_pages_for_i = 1
            else:
                n_pages_for_i = arr[count_n] // k + 1
            count_n += 1
            for l in range(1, n_pages_for_i+1):
                for j in tasks[:k]:
                    if j == l:
                        count += 1
                tasks[:k] = ''

        return count

