        if len(nums) == 1:
            return nums
        greater = list()
        less = list()
        support = nums[0]
        for number in nums:
            if number < support:
                less.append(number)
            else:
                greater.append(number)
         
        return self.quick_sort(less) + self.quick_sort(greater)

