class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


class Answer:
    def reverseList(self, head):
        previos = None
        current = head
        
        while current.next:
            previous = ListNode(current.val, next=previos)
            current = head.next
        
        return previous

