class Answer:
    cache = list()    
    def RepeatDecorator(self, func):
        def Wrapper(*args, **kwargs):
            hash_key = self.GenerateHashKey(func, *args, **kwargs)
            result = func(*args, **kwargs)
            if hash_key in cache:
                print('Функция с такими аргументами уже запускалась!')    
            cache.append(hash_key)
            return result
        return Wrapper
    
    def GenerateHashKey(self, func, *args, **kwargs):
        funcNameHash = hash(func.__name__)
        argsHash = hash(tuple(args))
        kwargsHash = hash(frozenset(kwargs))
        return funcNameHash + argsHash + kwargsHash

