    def getIntersectionNode(self, headA, headB):
        current_a = headA
        
        for node_a in iterateListNode(headA):
            value_a = node_a.val
            for node_b in iterateListNode(headB):
                value_b = node_b.val
                if value_a == value_b:
                    return node_a
        return None

