class Answer:
    def FindMedian(self, arr):
        n = len(arr)
        index = n // 2
        # Sample with an odd number of observations
        if n % 2:
            res = sorted(arr)[index]
            return res
        elif n < 1:
            res = None
        # Sample with an even number of observations
        res = sum(sorted(arr)[index - 1:index + 1]) / 2
        return res

