class Answer:
    def checkPossibility(self, nums):
        num_violations = 0
        for i in range(1, len(nums)):
            if nums[i - 1] > nums[i]:
                if num_violations == 1:
                    return False
                num_violations += 1
                if i < 2 or nums[i - 2] <= nums[i]:
                    nums[i - 1] = nums[i]
                else:
                    nums[i] = nums[i - 1]
        return True

class Answer:
    def checkPossibility(self, nums):
        cnt, previous = 0, None
        for digit in nums:
            if previous is None:
                previous = digit
                continue

            if digit < previous:
                cnt += 1

            if cnt > 1:
                return False

            previous = digit

        return True

