class Answer:
    def gen(res, m,arr,s,prefix=None):
    prefix = prefix or []
    if m==0:
        res.append(tuple(prefix))
        return 
    for i in range(len(arr)):
        if i not in s:
            prefix.append(arr[i])
            gen(res,m-1,arr,s.union({i}),prefix)
            prefix.pop()
    
    def perms(self, arr): 
        res =[]
        gen(res, len(arr),arr,set())
        return res

