    def perms(self, arr):
        
        def gen(res, m,arr,s,prefix=None):
            prefix = prefix or []
            if m==0:
                res.append(tuple(prefix))
                return 
            for i in range(len(arr)):
                if i not in s:
                    prefix.append(arr[i])
