class Answer:
    def perms(self, arr): 
        d = []
        pool = arr
        n = len(arr)
        inds = list(range(n))
        cycles = list(range(n, 0, -1))
        d.append(tuple(arr))
        while n:
            for i in reversed(range(n)):
                cycles[i] -= 1
                if cycles[i] ==0:
                    inds[i:] = inds[i+1:] + inds[i:i+1]
                    cycles[i] = n - i
                else:
                    j = cycles[i]
                    inds[i], inds[-j] = inds[-j], inds[i]
                    d.append(tuple(arr[i] for i in inds))
                    break
            else:
                return d
        return d

