class Answer:
    def jumpingOnClouds(self, clouds):
        jumps = 0
        x = 0
        while x < len(clouds)-1:
            if clouds[x+2] != 1:
                jumps+=1
                x += 2
            elif clouds[x+1] != 1:
                jumps+=1
                x+=1
            else:
                return
        return jumps
    
