class Answer:
    def quick_sort(self, nums):
        if len(set(nums)) < 2:
            return nums
        
        greater = list()
        less = list()
        support = nums[0]
        
        for number in nums:
            if number <= support:
                less.append(number)
                continue
            greater.append(number)
        
        less = self.quick_sort(less) 
        greater = self.quick_sort(greater)
        return [*less, *greater]

