import time

class Answer:
    def TimeDecorator(self, fn):
        def wrapper(*args, **kwargs):
            t0 = time.time()
            result = fn(*args, **kwargs)
            dt = (time.time() - t0) * 1000  # ms to sec
            print(f"Затрачено {dt} секунд")
            return result
        return wrapper

