class Answer:
    def calcMean(self, df1, df2, df3):
        all_df = pd.concat([df1, df2, df3])
        all_df = all_df.dropna()
        page1, page2, page3 = all_df.page1.mean(),               all_df.page2.mean(), all_df.page3.mean()
        new_row = {'page1':page1, 'page2':page2, 'page3':page3}
        all_df = all_df.append(new_row, ignore_index=True) 
        return all_df

