class Answer:
    def sieve(self, n): 
        if n <= 2:
            return []
        
        numbers = list(range(2, n + 1))
        index = 0
        p = numbers[index]
        
        while self.has_composite_number(index, numbers):
            numbers = list(filter(lambda number: number % p != 0 or number < p * 2, numbers))    
            maximal_index = len(numbers) - 1
            index += 1 
            index = index if maximal_index >= index else maximal_index
            p = numbers[index]
        
        return numbers
    
    def cross_composite_numbers(self, p, numbers):
        result_numbers = list()
        for index, number in enumerate(numbers):
            if number % p != 0:
                result_numbers.append(number)
            if number < (p * 2):
                result_numbers.append(number)
        return result_numbers
    
    def has_composite_number(self, index, numbers):
        maximal_index = len(numbers) - 1
        return index < maximal_index

