class Answer:
    def CountSpecialProblems(self, n, k, arr):
        count = 0
        page = 0
        for i in range(n):
            for st in range(1,(arr[i]-1)//k+2):
                page +=1
                z1 = k*(st-1)+1
                z2 = st*k
                if z2>arr[i]:
                    z2 = arr[i]
                if z2>=page>=z1:
                    count+=1
        return count

