class Answer:
    def jumpingOnClouds(self, clouds):
        # введите свой код ниже
        i = 1
        jump = 0
        while i < len(clouds - 1):
            if clouds[i] == 1:
                jump += 1
                i +=2
            else:
                if clouds[i+1] ==1:
                    jump +=1
                    i +=1
                else:
                    jump +=1
                    i+=2
        
                
                
        return jump

