class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        arr_sorted = sorted(arr, reverse=False)
        if len(arr_sorted) % 2 == 0:
            res = (arr_sorted[int(len(arr_sorted) / 2) - 1] + arr_sorted[int((len(arr_sorted) / 2))]) / 2
        else:
            res = arr_sorted[int((len(arr_sorted) // 2))]
        return res

