class Answer:
    def jumpingOnClouds(self, clouds):
        # введите свой код ниже
        n = len(clouds)
        c = [n+1]*n
        if clouds[0]==0:
            c[0] = 1
        if clouds[1]==0:
            c[1] = 1
            
        for i in range(2,n):
            if clouds[i] == 0:
                c[i]=min(c[i-1,c[i-2]])+1
        jumps = c[-1]
        return jumps

