class Answer:
    def PureIntersection(self, arr1, arr2):
        # введите свой код ниже
        res = []
        for i in arr1:
            for j in arr2:
                if i==j:
                    if len(res)>0:
                        flag = True
                        for k in res:
                            if k==i:
                                flag = False
                        if flag == True:
                            res.append(i)
                    else:
                        res.append(i)
                        break
        return res

