class Answer:
    def pairs(self, A, B):
        cort = ()
        temp_list = []
        if len(A) >= len(B):
            for k in range(0, len(A)):
                try:
                    check = B[k]
                except:
                    check = 0
                cort = (A[k], check)
                temp_list.append(cort)
        elif len(A) < len(B):
            for k in range(0, len(B)):
                try:
                    check = A[k]
                except:
                    check = 0
                cort = (check, B[k])
                temp_list.append(cort)
        return temp_list

