class Answer:
    def max_char(self, str1):
        dict_s = {}
        for letter in str1:
            if letter in dict_s:
                dict_s[letter] += 1
            else:
                dict_s[letter] = 1
        letter_val = max(dict_s, key=dict_s.get)
        key_val = max(dict_s.values())
        return str(letter_val), key_val

