class Answer:
    def perms(self, arr): 
        pool = tuple(arr)
        n = len(pool)
        r = n if arr
        for indices in product(range(n), repeat=r):
            if len(set(indices)) == r:
                yield tuple(pool[i] for i in indices)

class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        arr.sort()
        l = len(arr)
        if l % 2 == 0:
            res = (arr[l / 2 - 1] + arr[l / 2]) / 2
        else:
            res = arr[(l - 1) / 2 + 1]
        return res

