class Answer:
    def CountSpecialProblems(self, n, k, arr):
        book = []

        for p in range(n):
            t = list(range(1, arr[p] + 1))
            for i in range(0, len(t), k):
                book.append(t[i: i + k])
        count = 0
        for j in range(1, len(book) + 1):
            if j in book[j - 1]:
                count += 1
        
        return count

