class Answer:
    def jumpingOnClouds(self, clouds):
        jumps = [0] * len(clouds)
        jumps[1] = 1
        for i, el in enumerate(clouds):
            if el != 0:
                jumps[i] = float('inf')
        for j in range(2, len(clouds)):
            if clouds[j] == 0:
                jumps[j] = min([jumps[j - 2], jumps[j - 1]]) + 1

        return jumps

