class Answer:
    def twoSum(self, nums, target):
        index_start = 0
        while True:
            index_start += 1
            num1 = nums[index_start-1]
            for i in range(index_start, len(nums)):
                if num1 + nums[i] == target:
                    return [nums.index(num1), i]

