class Answer:
    def pairs(self, A, B):
        res = []
        if len(A) > len(B):
            B += [0 for i in range(len(A)-len(B))]
        elif len(B) > len(A):
            A += [0 for i in range(len(B)-len(A))]
        
        for i in range(len(A)):
            res.append((A[i], B[i]))
            
        return res

