class FreqStack:
    def __init__(self):
        self.value= []
        self.dikt = dict()
        self.rank = []
        
    def push(self,value):
        self.value.append(value)
        if self.dikt.get(value):
            self.dikt[value] += 1
        else:
            self.dikt[value] = 1
        self.rank.append(self.dikt[value])
    
    def pop(self):
        max_rank = max(self.dikt.values())
        for i in range(1,len(self.value)+1):
            if self.rank[-i]==max_rank:
                self.dikt[self.value[-i]] -= 1
                self.rank.pop(-i)
                self.value.pop(-i)
                break

