class Answer:
    def sieve(self, n): 
        a = [i for i in range(n+1)]  
        for i in range(2,len(a)):
            if a[i] == 0: continue
            else:
                for j in range(2*i,len(a),i):
                    a[j]=0
        res = []
        for each in a[2:]:
            if each!=0:
                res+=[each]
        return res

class Answer:
    def scoreOfParentheses(self, S):
        stack = [0]

        for x in S:
            if x == '(':
                stack.append(0)
            else:
                v = stack.pop()
                stack[-1] += max(2 * v, 1)

        return stack.pop()

