class Answer:
    def gcd(self, a, b):
        temp = 1
        if a > b:
            while a // b != 0:
                temp = a % b
                a = a // b
        elif a == b:
            temp = a
        else:
            while b // a != 0:
                temp = b % a
                b = b // a
        return temp

