class Answer:
    def maxSumTwoNoOverlap(self, A, L, M):
        a_len = len(A)
        if L+M > a_len: res = 0
        elif L+M == a_len: res = sum(A)
        else:
            if L<M: L,M = M,L
            al = dict()
            am = dict()
            for i in range(a_len-L+1):
                al[sum(A[i:i+L])]=A[0:i]+A[i+L:]
            res = max(al)
            A = al[max(al)]
            for i in range(len(A)-M+1):
                am[sum(A[i:i+M])]=''
            res += max(am)    
        return res

