class Answer:
    def quick_sort(self, nums):
        if len(nums) == 1:
            return nums
        lower = []
        greater = []
        pivot = nums.pop()
        
        for i in range(len(nums)):
            if nums[i] <= pivot:
                lower.append(nums[i])
            else:
                greater.append(nums[i])
                
        return quick_sort(self, lower) + [pivot] + quick_sort(self, greater)

