class Answer:
    def FindMedian(self, arr):
        l = len(arr)        
        if not l: return None
        middle = int(l/2)
        sorted_arr = sorted(arr)

        if l%2 == 0:
            res = (sorted_arr[middle] + sorted_arr[middle-1])/2
        else:
            res = sorted_arr[middle]

        return res

