class Answer:
    def quick_sort(self, nums):
        if len(arr) <= 1:
            return arr
        else:
            pivot = arr.pop()
        
        lower = []
        greater = []
    
        for i in arr:
            if i > pivot:
                greater.append(i)
            else:
                lower.append(i)
            
        return quick_sort(lower) + [pivot] + quick_sort(greater)

