class Answer:
    def CountSpecialProblems(self, n, k, arr):
        task = []
        res = []
        for i in range(n):
            t = 0
            while(t + k <= arr[i]):
                task.append([q + 1 for q in range(t, t + k)])
                t += k
            if(t <= arr[i]):
                task.append([q + 1 for q in range(t, arr[i])])

        for p in range(1, len(task)):
            if p in task[p - 1]:
                res.append(p)       
        return len(res)

