class Answer:
    def maxCandies(self, costs, coins):
        costs = sorted(costs)
        ind = [0]
        
        if min(costs)>coins:
            return 'Самая дешевая конфета стоит больше ', coins, ' монет, поэтому мальчик не сможет купить конфеты.'
        else:
            res = [str(costs[0])]
            k = costs[0]
            for i in range(1, costs):
                if costs[i]+k < coins:
                    k+=costs
                    ind.append(str(i))
                    res.append(str(costs[i]))
            return 'Мальчик может купить конфеты с индексами', ','.join(ind), 'потратив на них', ' + '.join(res), '=', coins

