class Answer:
    def sieve(self, n):
        lst = []
        sieve = set(range(2, n+1))
        while sieve:
            prime = min(sieve)
            lst.append(prime)
            sieve -= set(range(prime, n+1, prime))
        return lst

class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        if arr == []:
            return None
        arr = sorted(arr)
        l = len(arr)
        if (l % 2) != 0:
            a = int((l-1)/2)
            res = arr[a]
            return res
        else:
            a = int((l/2)-1)
            b = int(l/2)
            res = (arr[a] + arr[b]) / 2
            return res

