class Answer:
    def maxCandies(self, costs, coins):
        costs = sorted(costs)
        if min(costs)>coins:
            return 0
        else:
            k = 0
            sums = 0
            i = 0
            while costs[i]+sums <= coins and i<len(costs):
                    k+=1
                    sums+=costs[i]
                    i+=1
                    
            return k

