class Answer:
    
    def heapify(self, nums, h_size, root_index):
        lg = root_index
        lf_child = (2 * root_index) + 1
        rg_child = (2 * root_index) + 2
        
        if lf_child < h_size and nums[lf_child] > nums[lg]:
            lg = lf_child
            
        if lg != root_index:
            nums[root_index], nums[lg] = nums[lg], nums[root_index]
            heapify(nums, h_size, lg)
            
    def heap_sort(self, nums):
        n = len(nums)
        
        for i in range(n, -1, -1):
            heapify(nums, n, i)
        
        for i in range(n-1, 0, -1):
            nums[i], nums[0] = nums[0], nums[i]
            heapify(nums, i, 0)

