class Answer:
    def jumpingOnClouds(self, clouds):
        pos=len(clouds)-1
        jumps=0
        while pos > 0:
            if pos>1:
                if clouds[pos-2]==0:
                    pos-=2
                else:
                    pos-=1
            else:
                pos-=1
            jumps+=1
        return jumps

