class Answer:
    def max_char(self, str1):
        dictionary = dict()
        for l in str1:
            if(l not in dictionary):
                dictionary[l] = 1
            else:
                dictionary[l]+=1
        max_letter = max(zip(dictionary.values(), dictionary.keys()))[1]
        return list(max_letter, dictionary[max_letter])

