class Answer:
    def magic_dict(self, str):
        dct, dct_sort = {}, {}
        for s in str:
            dct[s] = dct.get(s, 0) + 1
        for key in sorted(dct):
            dct_sort[key] = dct[key]
        return dct_sort

class Answer:
    def pairs(self, A, B):
    res = []
    for i in range(min(len(A), len(B))):
        res.append((A[i], B[i]))
    for i in range(abs(len(A) - len(B))):
        if len(A) > len(B):
            res.append((A[i+len(B)], 0))
        else:
            res.append((0, B[i+len(A)]))
    return res

