import time

class Answer:
    def TimeDecorator(self, func):
        @functools.wraps(func)
        def wrapper_time_decorator(*args, **kwargs):
            start_time = time.perf_counter()
            value = func(*args, **kwargs)
            end_time = time.perf_couner()
            exc_time = end_time - start_time
            print(f'Затрачено {exc_time} секунд')
            return value
        return wrapper_time_decorator

