class Answer:
    def sieve(self, n):
        p = 2
        arr =[i for i in range(n + 1)]
        while p <= n:
            if arr[p] != 0:
                i = p + p
                while i <= n:
                    arr[i] = 0
                    i = i + p
            p += 1
            return list(set(arr[2:]).difference({0}))

