class Answer:
    def jumpingOnClouds(self, clouds):
        # введите свой код ниже
        jumps = 0
        while clouds:
            if len(clouds) >= 3:
                if clouds[2] == 0:
                    jumps += 1
                    clouds = clouds[2:]
                else:
                    jumps += 1
                    clouds = clouds[1:]
            elif len(clouds) == 2:
                jumps += 1
                break
            else:
                break
        return jumps
    
