        n = len(arr)
        arr = sorted(arr)
        mid_i = (n // 2)
        if n % 2 == 0:
            left_elem = arr[mid_i]
            right_elem = arr[mid_i+1]
            res = left_elem + right_elem / 2
        else:
            res = arr[mid_i]
        return res

