class Answer:
    def transp(self, matrix):
        matrixnew = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                matrixnew[j][i]=matrix[i][j]
        return matrixnew

class Answer:
    def transp(self, matrix):
        matrixnew = [[0]*(len(matrix)) for _ in range(len(matrix[0]))]
        for i in range(len(matrix[0])):
            for j in range(len(matrix[0])):
                matrixnew[j][i]=matrix[i][j]
        return matrixnew

class Answer:
    def transp(self, matrix):
        n,k = len(matrix), len(matrix[0])
        matrixnew = [[0]*n for _ in range(k)]
        for i in range(n):
            for j in range(k):
                matrixnew[j][i]=matrix[i][j]
        return matrixnew

