from math import factorial, sqrt

class Answer:
    def decomp(self, n):
        fact_n = factorial(n)
        Ans = []
        d = 2
        while d * d <= sqrt(fact_n):
            if fact_n % d == 0:
                Ans.append(d)
                fact_n //= d
            else:
                d += 1
        if fact_n > 1:
            Ans.append(fact_n)
        return Ans

