class Answer:
    def CalsStatistics(self, arr, type):
        if type == 'colwise':
            axis = 0
        else:
            axis = 1
            
        mean = arr.mean(axis=axis)
        var = arr.var(axis=axis)
        std = arr.std(axis=axis)
        sum = arr.sum(axis=axis)
        
        return mean, var, std, sum

