from math import factorial

class Answer:
    def decomp(self, n):
        n = factorial(n)
        dividers = []
        i = 2
        res = ''
        while n != 1:
            if n % i == 0:
                dividers.append(i)
                n = n // i
            else:
                i += 1
        dividers = Counter(dividers).most_common()
        for index, divider in enumerate(dividers):
            res += str(divider[0])
