class Answer:
    def decomp(self, n):
        n_fact = 1
        while n > 0:
            n_fact *= n
            n -= 1
        divider = 2
        numbers = []
        while n_fact > 1:
            i = divider
            if n_fact % i == 0:
                numbers.append(i)
                n_fact = n_fact / i
            else:
                while True:
                    i += 1
                    if n_fact % i == 0:
                        numbers.append(i)
                        n_fact = n_fact / i
                        break
        unique_numbers = set(numbers)
        degree = []
        for i in range(len(unique_numbers)):
            current = unique_numbers.pop()
            index = 0
            while index < len(numbers):
                if len(numbers) == 1:
                    degree.append(1)
                    break
                elif current == numbers[index]:
                    index += 1
                else:
                    degree.append(index)
                    numbers = numbers[index:]
                    break
        res = ''
        unique_numbers = set(numbers)
        for i in range(len(unique_numbers)):
            if degree[i] > 1:
                res += str(unique_numbers.pop()) + '^' + str(degree[i]) + ' '
            else:
                res += str(unique_numbers.pop()) + ' '
        return res.strip().replace(' ', ' * ')

