class Answer:
    def prime_number(num):
        for i in range(2, n // 2 + 1):
            if n % i == 0:
                return False
        return True
    
    def decomp(self, n):
        # введите свой код ниже
        n = int(input())
        num_fact = 1
        list_prime = []
        lst = [x for x in range(2,num + 1)]
        for _ in lst:
            if self.prime_number(_):
                list_prime.append(_)
        lst_out = []
        for i in list_prime:
            deg = 0    
            for j in range(len(lst)):
                while lst[j] % i == 0:
                    deg += 1
                    lst[j] = int(lst[j] / i)
            if deg > 1:
                lst_out.append(f'{i}^{deg}')
            elif deg == 1:
                lst_out.append(str(i))
        res = ' * '.join(lst_out)
        return res

