import math

class Answer:
    def decomp(self, n):
        n_fact = 1
        while n > 0:
            n_fact *= n
            n -= 1
            
        devider = 2
        numbers = []
        while devider * devider <= n_fact:
            while n_fact % devider == 0:
                numbers.append(devider)
                n_fact = n_fact / devider
            devider = devider + 1
        if n_fact > 1:
            numbers.append(int(n_fact))
        
        cnt = Counter(numbers)
        d = dict(cnt)
        
        l = list(d.items())
        res = ''
        for i in range(len(l)):
            if l[i][1] > 1:
                res += str(l[i][0]) + '^' + str(l[i][1]) + ' '
            else:
                res += str(l[i][0]) + ' '
        return res.strip().replace(' ', ' * ')

