            if check(x) == True:
                dd.append(x)
        con = []
        for i, v in enumerate(dd):
            nom = 1
            con.append(1)
            while math.factorial(n) % (v**nom) == 0:
                con[i] = nom
                nom +=1
        res = []
        for a, b in zip(dd, con):
            if b != 1:
                res.append('{}^{}'.format(a,b))
            else:
                res.append(str(a))

        res =  ' * '.join(res)
        

        return res

