class Answer:
    def decomp(self, n):
        # введите свой код ниже
        a = np.math.factorial(n)
        c = {}
        b = 2
        while b*b <= a :
            if a % b == 0:
                a //= b
                if b not in c.keys():
                    c[b] = 1
                else:
                    c[b] += 1
            else:
                b += 1
            if a > 1:
                c[a] = 1
        res = ' * '.join([('^'.join([str(i),str(c[i])])) if c[i] != 1 else str(i) for i in c.keys()])
        return res

