class Answer:
    def decomp(self, n):
        # введите свой код ниже
        p = []  # множители
        st = []  # степени
        factory = []
        i = 2
        while i < n:
            if (len([x for x in range(1, i // 2 + 1) if i % x == 0]) == 1):
                S = 0
                array_k = []
                k = 1
                while i ** k < n:
                    S += n // (i ** k)
                    k += 1
                p.append(i)
                st.append(S)
                i += 1
            else:
                i += 1
                continue
        for i in range(len(p)):
            if st[i] > 1:
                factory.append(str(p[i]) + "^" + str(st[i]))
            else:
                factory.append(str(p[i]))

        res = " * ".join(factory)

        return res

