class Answer:
    def _factorize(self, number):
        factor = 2
        while factor * factor <= number:
            degree = 0
            while number % factor == 0:
                degree += 1
                number /= factor
            if degree > 0:
                yield factor, degree
            if number == 1:
                return
        yield number, 1
    
    def decomp(self, n):
        return " * ".join(
            f"{factor}^{degree}" 
                if degree > 1 
                else f"{factor}"
            
            for factor, degree
            in self.factorize(n)
        )

