class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        arr = sorted(arr)
        if len(arr)%2 != 0:
            i = int(len(arr)/2-0.5)
            res = arr[i]
        else:
            i = int(len(arr)/2)
            res = (arr[i-1]+arr[i])/2
        return res

