from collections import Counter

class Answer:
    
    def _factorize(self, number):
        factor = 2
        while factor * factor <= number:
            degree = 0
            while number % factor == 0:
                degree += 1
                number //= factor
            if degree > 0:
                yield factor, degree
            if number == 1:
                return
            factor += 1
        if number > 1:
            yield number, 1

    def decomp(self, n):
        factorization = Counter()
        for k in range(2, n+1):
            factorization.update(
                dict(self._factorize(k))
            )
        return " * ".join(
            f"{factor}^{degree}" 
                if degree > 1 
                else f"{factor}"        
            for factor, degree
            in factorization.items()
    )

