from collections import Counter
class Answer:
    def decomp(self, n):
        lst_simple = []
        for i in range(2, n + 1):
            flag = True
            for j in range(2, i):
                if i % j == 0:
                    flag = False
            if flag:
                lst_simple.append(i)
        res = []

        for i in range(2, n + 1):
            if i in lst_simple:
                res.append(i)
            else:
                m = i
                while m != 1:
                    if m in lst_simple:
                        res.append(m)
                        break
                    k = []
                    for a in lst_simple:
                        if m % a == 0:
                            k.append(a)
                            m = int(m / a)
                            break
                    res.extend(k)

        c = Counter(res)
        s = []
        for k, v in c.items():
            if v != 1:
                s.append(f'{k}^{v}')
            else:
                s.append(f'{k}')
        return ' * '.join(s)

