def inc(dic, key, increment=1):
    key = int(key)
    increment = int(increment)
    if key in dic:
        dic[key] = dic[key]+increment
    else:
        dic[key] = increment

def is_prime(n):
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    sixk = 6
    limit = n ** (0.5) + 1
    while sixk <= limit:
        if n % (sixk - 1) == 0:
            return False
        if n % (sixk + 1) == 0:
            return False
        sixk += 6
    return True

def decomp_factorial(n):
    factors = {}
    for i in range(1, n + 1):
        if is_prime(i):
            c = i
            entries = 0
            while c <= n:
                entries += int(n / c)
                c *= i
            
            inc(factors, i, entries)
    return factors

def factors_to_str(factors):
    keys = []
    for key in factors:
        keys.append(key)
    keys.sort()
    substrs = []
    for key in keys:
        if factors[key] == 1:
            substrs.append(str(key))
        else:
            substrs.append("%d^%d" % (key, factors[key]))
    return " * ".join(substrs)

class Answer:
    def decomp(self, n):
        # введите свой код ниже
        return factors_to_str(decomp_factorial(n))

