class Answer:
    def isValid(self, s):
        brackets = {
            "(": ")",
            "{": "}",
            "[": "]"
        }
        stack = []
        for b in s:
            if b in brackets:
                stack.append(b)
            elif b in brackets.values():
                if not stack or b != brackets[stack[-1]]:
                    return False
                stack.pop()
                    
        return False if stack else True

