class Answer:
    def decomp(self, n):
        # введите свой код ниже
        passed = []
        res_array = []
        for i in range(2, n):
            if i not in passed:
                count = 0
                current = i
                for j in passed:
                    if j * i not in passed and j * i < n:
                        passed.append(j * i)
                while current <= n:
                    count = count + n // current
                    passed.append(current)
                    current = current * i                    
                if count == 1:
                    res_array.append(str(i))
                elif count > 1:
                    res_array.append(f"{i}^{count}")                    
        return ' * '.join(res_array)
print(Answer().decomp(12))

