from collections import Counter 

class Answer:
    def decomp(self, n):
        # введите свой код ниже
        n_f = 1
        # Найдем факториал заданного числа
        for i in range(1, n+1):
            n_f *= i # Факториал
            
        d = 2 # Первый делитель
        s = []

        # Найдем массив всех делителей
        while (d <= n_f/2): 
            if (n_f % d) == 0:
                s.append(d)
                n_f = n_f/d
            else:
                d += 1
        if n_f > 1:
            s.append(int(n_f)) # Массив всех делителей
            
        count = Counter(s) # Сколько раз встречается каждый делитель в нашем числе (n)  
        
        line = [] # Строка с результатом в необходимом виде
        for key, value in count.items():
            if value != 1:
                line.append(str(key)+'^'+str(value))
            else:
                line.append(str(key))
                
        res = " * ".join(line) # Финальный результат
            
        return res

