class Answer:
    import math
    from functools import cache
    from collections import Counter
    def decomp(self, n):
        # введите свой код ниже
        @cache
        def fact(num):
            return num * fact(num-1) if num else 1

        def factorize(num):
            line = [] 
            num = fact(num)
            for i in range(2, int(math.sqrt(num)) + 1): # обычно делитель не будет больше корня
                while (num % i == 0): # while, а не if
                    line.append(i)
                    num //= i # убираем множитель из числа

            if (num != 1): # но один делитель может быть больше корня
                line.append(num)
            return " * ".join(f'{x}^{y} ' if y != 1 else f'{x}' for x,y in (dict(Counter(line))).items())
            # print(res)
        
        return factorize(n)

