class Answer:
    def decomp(self, n):
        def factorial(n):
            if n == 1:
                return 1
            else:
                return (n * factorial(n-1))

        def factor(n):
            res = []
            d = 2
            while d * d <= n:
                if n % d == 0:
                    res.append(d)
                    n //= d
                else:
                    d += 1
            if n > 1:
                res.append(n)
            return res

        lst = factor(factorial(n))
        dct = {x:lst.count(x) for x in lst}
        res = []
        for i in dct.keys():
            if dct[i]  != 1:
                res.append(f'{i}^{dct[i]}')
            else:
                res.append(f'{i}')
        res = ' * '.join(res)

        return res

