class Answer:
    def CountSpecialProblems(self, n, k, arr):
        # введите свой код ниже
        if k = 1:
            return(arr[0])
        pages = sum(arr)//k+1
        spec = 0
        nic = 0
        for i in arr:
            pag = i//k+1
            if i > pag+nic:
                if nic+1 == k:
                    spec+=2
                else:
                    spec+=1
            else:
                continue
            nic+=pag
        return spec

