from collections import Counter

class Answer:
    def decomp(self, num):
        def factorize(n):
            cur_n = n
            n = 2
            while n ** 2 <= cur_n:
                if cur_n % n == 0:
                    cur_n = cur_n // n
                    cnt.append(n)
                else:
                    n += 1
            if cur_n > 1:
                cnt.append(cur_n)

        cnt = []
        if num < 2:
            return ''
        for n in range(2, num + 1):
            factorize(n)
        out = ''
        for k, v in Counter(cnt).items():
            if v == 1:
                out += f'{k} * '
            else:
                out += f'{k}^{v} * '
        return out[:-2]

