class Answer:
    
    def get_simple_numbers(self, n):
        numbers = [1] * (n + 1)
        res = []
        i = 2
        while i <= n:
            k = 1
            if numbers[i] == 1:
                res.append(i)
                while k * i <= n:
                    numbers[k * i] = 0
                    k += 1
            i += 1
        return res
    
    def get_simple_div_with_degs(self, n, simple_numbers):
        res = []
        for s in simple_numbers:
            deg = 0
            while n % s == 0:
                deg += 1
                n /= s
            res.append(deg)
        return res
    
    def decomp(self, n):
        # введите свой код ниже
        simple_numbers = self.get_simple_numbers(n)
        # print(simple_numbers)
        degs = [0] * len(simple_numbers)
        for k in range(2, n+1):
            cur_degs = self.get_simple_div_with_degs(k, simple_numbers)
            for i in range(len(simple_numbers)):
                degs[i] += cur_degs[i]
        res = ''
        #return res
        for i in range(len(simple_numbers)):
            if degs[i] > 0:
                if i > 0:
                    res += ' * '
                res += str(simple_numbers[i])
            if degs[i] > 1:
                res += '^' + str(degs[i])
        return res

