class Answer:
    def CountSpecialProblems(self, n, k, arr):
        # введите свой код ниже
        count = 0
        page = 1
        for i in range(n):
            current = 1
            while current < arr[i]:
                if current <= page < current + k <= arr[i]:
                    count += 1
                current += k
                page += 1
        return count
