from collections import defaultdict


class Answer:
    def decomp(self, n):
        p = defaultdict(int)
        for i in range(2, n+1):
            div = 2
            while i > 1:
                while i % div == 0:
                    i //= div
                    p[div] += 1
                div += 1
        return " * ".join(
            f"{k}^{v}" if v > 1 else str(k) 
            for k, v in p.items()
        )

