import math


class Answer:
    def decomp(self, n):
        factori = math.factorial(n)
        figures = []
        while factori != 1:
            tmp = 2
            last_tmp = 2
            degree = 0
            while factori != 1:
                if factori % tmp == 0:
                    factori /= tmp
                    if tmp == last_tmp:
                        degree += 1
                    else:
                        if degree > 1:
                            figures.append(str(last_tmp) + '^' + str(degree))
                        else:
                            figures.append(str(last_tmp))
                        degree = 1
                    if factori == 1.0:
                        if degree > 1:
                            figures.append(str(tmp) + '^' + str(degree))
                        else:
                            figures.append(str(tmp))
                    last_tmp = tmp
                else:
                    tmp += 1
        return ' * '.join(figures)

