class Answer:
    def CountSpecialProblems(self, n, k, arr):
        page = 1
        count = 0
        for chapter in range(0, n):
            if arr[chapter] < page:
                page += 1
                continue

            for i in range(0, arr[chapter], k):
                if page > k:
                    return count

                if i < k:
                    count += 1

                page += 1

        return count

class Answer:
    def CountSpecialProblems(self, n, k, arr):
        page = 1
        count = 0
        for ch in arr:
            for i in range(1, ch + 1):
                if page == i:
                    count += 1

                if i % k == 0:
                    page += 1

            if i % k != 0:
                page += 1

        return count

