from math import factorial
from collections import Counter 

class Answer:
    def decomp(self, n):
        factors = []
        n = factorial(n)
        
        d = 2
        while d * d <= n:
            if n % d == 0:
                factors.append(d)
                n //= d
            else:
                d += 1
        if n > 1:
            factors.append(n)
        
        count = Counter(factors)
        decomposition = [f'{a}^{b}' if b != 1 else f'{a}' for a, b in count.items()]
        res = " * ".join(decomposition)
        
        return res
        return res

