import math


def get_simple_divisor(val: int):
    divisor = 2

    while True:
        if val % divisor == 0:
            return divisor
        
        if divisor > 10000:
            return val

        divisor += 1


def get_unique_elements_count(lst: list):
    res = []
    tmp = []

    for val in lst:
        if len(tmp) == 0:
            tmp = [val, 1]

        elif val == tmp[0]:
            tmp[1] += 1

        else:
            res.append(tuple(tmp))
            tmp = [val, 1]

    res.append(tuple(tmp))
    return res


class Answer:
    def decomp(self, value):
        if not isinstance(value, int) or value < 2:
            return ''
 
        value = math.factorial(value)
        divisors = []
    
        while value > 1:
            divisor = get_simple_divisor(value)
            value //= divisor
            divisors.append(divisor)
    
        res = [f'{num}' + (f'^{degree}' if degree > 1 else '') for num, degree in get_unique_elements_count(divisors)]
        return ' * '.join(res)


