class Answer:
    def CountSpecialProblems(self, n, k, arr):
        # введите свой код ниже
        if arr == []:
            return None
        
        page_count = 0
        
        for i in arr:
            page_count += ceil(i / k)

        pages_arr = list(range(1, page_count+1))

        exes_arr = []
        
        for i in arr:
            exes_nums = list(range(1, i+1))
            while exes_nums:
                row = []
                j=0
                while j < k and exes_nums:
                    row.append(exes_nums[0])
                    exes_nums.pop(0)
                    j += 1
                exes_arr.append(row)    

        count = 0
        for i in pages_arr:
            if i in exes_arr[i-1]: count += 1

        return count

