class Answer:
    def decomp(self, n):
        kek = {}
        res = ""
        for i in range(2, n+1):
            lol = i
            div = 2
            while lol != 1:
                if lol % div != 0:
                    div+=1
                else:
                    try:
                        kek[div] += 1
                    except:
                        kek[div] = 1
                    lol = lol // div
        for i in kek:
            if kek[i] > 1:
                res += f"{i}^{kek[i]}"
            else:
                res += f"{i}"
            res += " * "
        return res[:-3]

