from math import factorial
from collections import Counter 

class Answer:
    def decomp(self,n):
        factors = []
        n = factorial(n) #определяем факториал числа
        d = 2 #первый делитель
        while d * d<=n:
            if n%d==0:
                factors.append(d)
                n//=d
            else:
                d=+1   
        if n>1:
            factors.append(n)
        counter=Counter(factors)
        decomposition = [f'{a}^{b}' if b!=1 else f'{a}' for a,b in counter.items()]
        res="*".join(decomposition)
        return res

