class Answer:
    def CountSpecialProblems(self, n, k, arr):
        # введите свой код ниже
        count = 0
        num_page = 1 # номер страницы
        obj_cntr = 0 # счетчик задач на странице
        for i in range(0, n):
            for j in range(1, arr[i]+1): # j - номер задачи
                obj_cntr += 1
                if obj_cntr > k:
                    num_page += 1
                if j == num_page:
                    count += 1
            num_page += 1
            obj_cntr = 0
        return count

