from collections import defaultdict

class Answer:
    def decomp(self, n):
        # введите свой код ниже
        primfac = defaultdict(int)
        for ghost in range(2, n+1):
            i = 2
            ghost_in = ghost
            while i * i <= ghost:
                while ghost_in % i == 0:
                    if primfac[i] is None:
                        primfac[i] = 1
                    else: 
                        primfac[i] = primfac[i] + 1
                    ghost_in = ghost_in / i
                i = i + 1
            if ghost_in > 1:
                ghost_in = int(ghost_in)
                if primfac[ghost_in] is None:
                    primfac[ghost_in] = 1
                else:
                    primfac[ghost_in] = primfac[ghost_in] + 1
        res = ''
        for prime, power in primfac.items():
            if power == 1:
                res = res + ' * {}'.format(prime)
            else:
                res = res + ' * {}^{}'.format(prime, power)
        res = res.replace(' * ', '', 1)
        return res

class Answer:
    def bubble_sort(self, nums):
        swapped = True
        while swapped:
            swapped = False
            for i in range(len(nums) - 1):
                if nums[i] > nums[i + 1]:                   
                    nums[i], nums[i + 1] = nums[i + 1], nums[i]                    
                    swapped = True
            return nums
