class Answer:
    def decomp(self, n):
    # factorial
        f = 1
        for el in range (2, n + 1):
            f *= el
    #primes
        factors = []
        div = 2
        while(div <= f):
            if f % div == 0:
                factors.append(div)
                f = f/div
            else:
                div += 1
        if f > 1:
            factors.append(f)
    
        count = Counter(factors)
        terms = (str(prime) if power == 1 else f"{prime}^{power}" for prime, power in count.items())
        res = " * ".join(terms)
    
        return res

