class Answer:
    def gcd(self, a, b):  
        max=0
        if a>=b:
            max=a
        else:
            max=b
        result=1
        for i in range(1,max):
              if a%i==0 and b%i==0:
                    result*=i
                    a/=i
                    b/=i
        return result

