              for j in range(i+1, len(arr)):
                    if arr[i]>arr[j]:
                          a=arr[j]
                          arr[j]=arr[i]
                          arr[i]=a
        if len(arr)%2==0:
              return (arr[len(arr)//2-1]+arr[len(arr)//2])/2
        else:
              return arr[len(arr)//2]

