class Answer:
    def list_cond(self, start, stop, n_div):

        if n_div == 0:
            return -1

        # Прямое направление перечисление (forward) или наоборот
        fwd = 1 if start <= stop else -1

        # Неэффективно расходуем память
        res = list(range(start, stop + 1 * fwd, 1 * fwd))
        
        res = [i for i in res if (i % n_div == 0)]
        
        return res

