class Answer:
    def decomp(self, n):
        res_dict = {}
        for number in range(2, n+1):
            step_number=number
            i = 2
            while step_number != 1 and i <= number:
                if step_number % i == 0:
                    if i in res_dict:
                        res_dict[i] += 1
                    else:
                        res_dict[i] = 1
                    step_number /= i
                else:
                    i+=1
        res_list = [f'{number}^{power}' if power !=1 else f'{number}' for number, power in res_dict.items()]
        return ' * '.join(res_list)
print(Answer().decomp(12))

