class Answer:
    def maxCandies(self, costs, coins):
        for i in range(0,len(costs)):
            for j in range(i+1,len(costs)):
                if costs[j]<costs[i]:
                    p=costs[i]
                    costs[i]=costs[j]
                    costs[j]=p
        result=0
        for i in costs:
            if coins>=i:
                result+=1
                coins-=i
            else:
                break
        return result

