class Answer:
    simple = []
    def decomp(self, n):
        a = []
        for i in range(2,n+1):
            simple = 2
            while i>1:
                if i%simple==0:
                    a.append(simple)
                    i = i//simple
                else:
                    simple += 1
        numbers = list(set(a))
        degrees = [a.count(num) for num in numbers]
        res = ''
        for i,num in enumerate(numbers):
            if degrees[i]!=1:
                res += str(num) + '^' + str(degrees[i]) 
            else:
                res += str(num)
            if i!=len(numbers)-1:
                res += ' * '
        return res

