class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        arr = sorted(arr)
        if len(arr)%2==0:
            ind = int(len(arr)/2)
            res = (arr[ind-1]+arr[ind])/2
        else:
            ind = int(len(arr)//2)
            res = arr[ind]
        return res

