class Answer:
    def anagram(self, word1, word2):
        if len (word1)!=len(word2):
            return False
        r=0
        for i in word1:
            for j in word2:
                if i==j:
                    r+=1
                    j=''
                    break
        if r==len(word1):
            return True
        else:
            return False

