class Answer:
    def decomp(self, n):
        _dict, _result = {}, []
        for i in range(2, n + 1):
            k = 2
            while i > 1:
                while i % k == 0:
                    _dict.setdefault(k, 0)
                    _dict[k] += 1
                    i //= k
                k += 1
        for key in sorted(_dict.keys()):
            if _dict[key] == 1:
                _result.append(f"{key}")
            else:
                _result.append(f"{key}^{_dict[key]}")
        return " * ".join(_result)

