class Answer:
    def isprime(self, n):
        if n == 1:
            return False
        for x in range(2, n):
            if n % x == 0:
                return False
        return True


    def f1(self, p, m):
        b = 0
        d = p
        i = 1
        while d < m:
            b = b + m // d
            i += 1
            d = p ** i
    # print(a)
        return b
    

    def decomp(self, n):
        res_mass = []
        for i in range(n + 1):
            if i > 1:
                if self.isprime(i):
                    res_mass.append((i, self.f1(i, n)))
        #print(res_mass)
        ret_str = ''
        for i in res_mass:
            if i[1] == 1:
                ret_str += "%s * " % (i[0])
            else:
                ret_str += "%s^%s * " % (i[0], i[1])
        ret_str=ret_str[:-3]
        return ret_str
        #print(ret_str)

