            for bracket in brackets:
                s = s.replace(bracket, "")
        return not s

class Answer:
    def findDuplicate(self, nums):
        duplicates = {}
        
        for item in nums:
            if item not in duplicates:
                duplicates[item] = 0
            duplicates[item] += 1
            
        result = {key: value for key, value in duplicates.iteritems() if value > 1}
        return result.keys()

