from collections import Counter

class Answer:
    def decomp(self, n):
        res = [i for i in range(2, n+1)]
        dels = []
        for i in res:
            x = 2 
            while x < math.floor(math.sqrt(i))+1:
                if (i%x==0):
                    dels.append(x)
                    i = i/x
                    x = 2
                else:
                    x += 1
            dels.append(i)
            cnt = Counter(dels)
            res = ' * '.join([f'{k}^{v}' if v>1 else f'{k}' for k,v in cnt.items()])
        return res

