class Answer:
    def CountSpecialProblems(self, n, k, arr):
        count = 0
        book = []
        for section_tasks in arr:
            pages = 0
            counter = section_tasks
            while counter > 0:
                pages += 1
                counter -= k
            tasks = [i for i in range(1, section_tasks + 1)]

            for i in range(pages):
                book.append([tasks.pop(0) if tasks else None for _ in range(3)])
        page = 1
        for nums in book:
            if page in nums:
                count += 1
            page += 1
        return count

