import re


class Answer:
    def rgx_phn(self, phones):

        if phones is None:
            raise AttributeError('An attribute should not be None')

        res = []

        trim = re.compile(r'(?:^\\+?|[()\\s-]*)')

        check = re.compile(r'(?:7|8)([0-9]{3})([0-9]{3})([0-9]{4})')

        for i in phones:
            t = trim.sub('', i)
            c = check.match(t)
            if (len(t) == 11 and c):
                res.append(f'+7({c[1]}){c[2]}-{c[3]}')
            else:
                res.append(-1)

        return res

