class Answer:
    def list_numbers(self, start, stop):

        res = []
        i = start
        step = 1

        if start <= stop:
            while i <= stop:
                res.append(i)
                i += step
        else:
            while i >= stop:
                res.append(i)
                i -= step

        return res

