class Answer:
    def list_numbers(self, start, stop):

        res = []
        i = start
        step = 1

        if start <= stop:
            while i <= stop:
                res.append(i)
                i += step
        else:
            while i >= stop:
                res.append(i)
                i -= step

        return res

class Answer:
    def list_numbers(self, *args, **kwargs):
        return "my wrong solution"

class Answer:
    def list_cond(self, start, stop, n_div):

        if n_div == 0:
            return -1

        # Прямое направление перечисление (forward) или наоборот
        fwd = 1 if start <= stop else -1

        # Неэффективно расходуем память
        res = list(range(start, stop + 1 * fwd, 1 * fwd))
        
        res = [i for i in res if (i % n_div == 0)]
        
        return res

