class Answer:
    def sort_dict(self, d, type, order):
        if type == "keywise":
            idx = 0
        else:
            idx = 1

        if order == "desc":
            reverse = True
        else:
            reverse = False

        return dict(sorted(d.items(), key=lambda x: x[idx], reverse=reverse))

