from math import floor
import math

def isPrime(n):
      if n % 2 == 0:
          return n == 2
      d = 3
      while d * d <= n and n % d != 0:
          d += 2
      return d * d > n

class Answer:
        

    def decomp(self, n):
        divs = [i for i in list(range(2,n+1)) if isPrime(i)]
        res = []
        for div in divs:
            temp = 0
            degree = 0
            while(True):
                degree += 1
                temp_item = floor(float(n)/(math.pow(div,degree)))
                if temp_item == 0:
                    break
                temp += temp_item
            res.append([div,temp]) 
        
        result = []

        for pair in res:
          if pair[1] == 1:
            result.append(str(pair[0]))
          else:
            result.append(str(pair[0]) + '^' + str(pair[1]))

        return ' * '.join(result)

