        return res

class Answer:
    def is_prime(self, a):
        for i in range(3, int(a**0.5), 2):
            if a % i:
                return False
        return True

    def primes(self, num):
        my_list = [2]
        for i in range(3, num+1, 2):
            if self.is_prime(i):
                my_list.append(i)
        return my_list

    def decomp(self, n):
        primes_ls = self.primes(n)
        factors = {}
        for i in range(2, n+1):
            k = i
            for j in primes_ls:
                if j > k:
                    break
                while k % j == 0:
                    factors[j] = factors.get(j, 0) + 1
                    k //= j
        res = ' * '.join(list(map(lambda x,y: [f'{x}^{y}',f'{x}'][y == 1], factors.keys(), factors.values())))
        return res

