class Answer:
    def CountSpecialProblems(self, n, k, arr):
        count, page = 0, 1
        for i in range(n):
            for task in range(arr[i]):
                count += (task == page + (task - 1) // k)                
            page += arr[i]//k + [0,1][arr[i]%k]
        return count
    
