class Answer:
    def decomp(self, n):
        # введите свой код ниже
        def factorial(num):
            if num == 0 or num == 1:
                return 1
            return num*factorial(num-1)
        number = factorial(n)
        factors = []
        i = 2
        while i <= number:
            if number % i == 0 :
                number = number / i 
                factors.append(i)
            else:
                i = i+1
        answer = []
        for each in set(factors):
            if factors.count(each) == 1:
                answer.append(f'{each}')
            else:
                answer.append(f'{each}^{factors.count(each)}')
        return (" * ").join(answer)
