class Answer:
    def CountSpecialProblems(self, n, k, arr):
        #необходимо определить сколько задач будет на последней странице
        #
        count = 0
        page = 1
        for section in range(0,n):
            for i in range(1, arr[section]+1):
                while arr[section] > 0:
                    if i == page:
                        count += 1
                    arr[section] -= k
                    page += 1
        
        return count
