class Answer:
    def CountSpecialProblems(self, n, k, arr):
        #задачник
        excercise_book = {}
        #количество разделов(больше на единицу, учитывая механизм работы range)
        sections       = n + 1
        #количество страниц задачника
        page           = 0
        #количество совпадений номера задачи с номером текущий страницы
        count          = 0
        
        for i in range(1,sections):
            #записываем количество задач для раздела
            #в переменную exc(exercises)
            exc    = arr[i-1]           
            while exc > 0:
                start = arr[i-1] - exc + 1 #число, с которого начнётся нумерация задач очередной страницы
                if exc < k:
                    end = start + arr[i-1] % k
                else:
                    end = start + k
                page += 1
                exc -= k
                if [x for x in range(start, end) if x == page] != []:
                    count += 1   
        return count
