class Answer:
        def decomp(self, n):
        # введите свой код ниже
            def isPrime(n):
                d = 2
                while n % d != 0:
                    d += 1
                return d == n
    
    
            def Prime(n, myList):
                d = 2
                while n % d != 0:
                    d += 1
                if n != d:
                    Prime(n // d, myList)
                    Prime(d, myList)
                else:
                    myList.append(n)
    
    
            res = str()
            firstList = []
            for i in range(2, n + 1):
                if isPrime(i):
                    firstList.append(i)
                else:
                    Prime(i, firstList)
    
            myDict = dict(Counter(firstList))
            for item in myDict.items():
                if item[1] != 1:
                    res += str(item[0])+'^'+str(item[1])+' * '
                else:
                    res += str(item[0]) + ' * '
            res = res[:len(res)-2]
            return res

