class Answer:
    def CountSpecialProblems(self, n, k, arr):
        # введите свой код ниже
        count2 = []
        i = 0
        while i <= n-1:
            page = int(arr[i] / k)  # получаем количество страниц
            for m in range(page):  # перебираем страницы
                for d in range(k):  # перебираем количество задач на странице
                    if m == d:  # если числа равны, добавляем
                        count2.append(m)
            for m in range((page-1)*k+1,arr[i]+1):
                for d in range(k+1):
                    if m == d:
                        count2.append(m)
            i += 1
        count1 = set(count2)
        count = len(count1)-1
        return count

