class Answer:
    def maxCandies(self, costs, coins):
      count = 0
      while coins > 0:
        coins -= min(costs)
        index_min = min(range(len(costs)), key=costs.__getitem__)
        costs.pop(index_min)

        if coins >= 0:
          count += 1
      
      return count

