class Answer:
    
    def decomp(self, n):
        # введите свой код ниже
        fact = math.factorial(n)
        counter = 0
        res = []
        while fact > 1:
            k = 0
            for i in range(2, fact):
                for j in range(2, i):
                    if i%j == 0:
                        k += 1
                if k == 0:
                    res.append(i)
                    res.append('^')
                    while fact%i == 0:
                        fact /= i
                        counter += 1
                    res.append(counter)
            res.append(' * ')
                   
        return res
    
