class Answer:
    def jumpingOnClouds(self, clouds):
        jumps_arrr = [0]
        maxx = len(clouds)
        if maxx == 2:
            return 1
        if clouds[1] == 0:
            jumps_arrr.append(1)
        else:
            jumps_arrr.append(maxx+1)
        for i in range(2,maxx):
            if clouds[i] == 1:
                jumps_arrr.append(maxx+1)
            else:
                jumps_arrr.append(min(jumps_arrr[i-1],jumps_arrr[i-2])+1)
        return jumps_arrr[maxx-1]

class Answer:
    def kidsWithCandies(self, candies, extraCandies):
        result = []

        for candi in candies:
            copy_candies = candies.copy()
            copy_candies.remove(candi)
            if (candi + extraCandies) * len(copy_candies) > sum(copy_candies):
                result.append(True)
            else:
                result.append(False)

        return result

