class Answer:
    def list_add_num(self, ref_list, start, stop, num):

        if len(ref_list) < start + 1  or len(ref_list) < stop + 1:
            return -1

        start, stop = min(start, stop), max(start, stop)

        num_range = stop - start + 1

        num_list = [num,] * num_range

        ref_list[start:stop+1:] = list(map(sum, zip(ref_list[start:stop+1:], num_list)))

        return ref_list

