import math
class Answer:
    
    def decomp(self, n):
        # введите свой код ниже
        fact = math.factorial(n)
        i = 2
        res = ''
        r = []
        while fact > 1:
            counter = 0
            k = 0
            for j in range(2, i):
                if i%j == 0:
                    k += 1
            if k == 0:
                r.append(str(i))
                while fact%i == 0:
                    fact = fact / i
                    counter += 1
                if counter > 1:
                    r.append('^')
                    r.append(str(counter))
                   
                if fact != 1: 
                    r.append(' * ')
            i += 1 
            res = ''.join(r)
        return res
    
