class Answer:
    def update_dict(self, d, add):
        res = d.copy()

        # пробегаемся по всем элементам add
        for k, v in add.items():
            # если такой ключ уже есть в res
            if k in res:
                # если значение по такому ключу - уже список
                if isinstance(res[k], list):
                    # тогда просто добавляем элемент
                    res[k].append(v)
                else:
                    # иначе формируем список
                    res[k] = [res[k], v]
            else:
                # если такого ключа вообще нет, просто добавляем
                res[k] = v

        return res

    
