class Answer:
    def minOperations(self, nums):
        i = 0
        k = 0
        for i in range(len(nums) - 1):
            if nums[i] >= nums[i + 1]:
                while nums[i] >= nums[i + 1]:
                    nums[i + 1] = nums[i + 1] + 1
                    k += 1
            i += 1
        return k


