class Answer:
    def FindMedian(self, arr):
        # введите свой код ниже
        arr.sort()
        if len(arr) % 2 == 0:
            num_val = int(len(arr)/2)
            res = (arr[num_val-1] + arr[num_val]) / 2
        else:
            res = arr[floor(len(arr)/2)]
        return res

