class Answer:
    def cnt_frq(self, names):
        res = {}
        for i in range(len(names)):
            count = 1
            for s in range(len(names)):
                if names[i] in res:
                    count += 0
                else:
                    if names[i] == names[s]:
                        count+=1
            res[names[i]] = count
        res=sorted(res.items())
        return res
