class Answer:
    def CalsStatistics(self, arr, type):
        if type == 'colwise':
            mean=arr.mean(axis=0)
            var=arr.var(axis=0)
            std=arr.std(axis=0)
            sum = arr.sum(axis=0)
        elif type == 'rowwise ':
            mean=arr.mean(axis=1)
            var=arr.var(axis=1)
            std=arr.std(axis=1)
            sum = arr.sum(axis=1)
        else:
            mean=arr.mean()
            var=arr.var()
            std=arr.std()
            sum = arr.sum()
        
        return mean, var, std, sum
