import numpy as np

class Answer:
    def fizzbuzztest(self):
        n=np.arange(1,100)
        n_1 = n.astype(str)
        for i in range(len(n)):
            if n[i] % 3 == 0:
                n_1[i] = 'Fizz'
            if n[i] % 5 == 0:
                n_1[i] = 'Buzz'
            if n[i] % 3 == 0 and n[i] % 5 == 0:
                n_1[i] = 'FizzBuzz'      
        return (n_1)    

