        sq = n**0.5
        for i in primes:
            if n % i == 0:
                break
            if i > sq:
                primes.append(n)
                yield n
                break
                
class Answer:
    def decomp(self, n):
        # введите свой код ниже
        r = {}
        for nn in range(2, n + 1):
            while nn > 1:
                for i in gen_primes():
                    d, m = divmod(nn, i)
                    if m == 0:
                        r[i] = r.get(i, 0) + 1
                        nn = d
                        break
        res = ' * '.join([f'{k}^{v}' if v > 1 else f'{k}'
                          for k, v in r.items()])
        return res

