class Answer:
    def CountSpecialProblems(self, n, k, arr):
        # введите свой код ниже
        s = 0
        count = 0
        for n in range(n):
            d, m = divmod(arr[n], k)
            ex = 1
            for s in range(s + 1, s + d + bool(m) + 1):
                nex = ex + k
                if nex > arr[n]:
                    nex = arr[n] + 1
                if ex <= s < nex:
                    count += 1
                ex = nex
        return count

