from math import factorial as f
class Answer:  
    def decomp(self, n):
        # введите свой код ниже
        self.n = f(n)
        lst = []
        while not self.n % 2:
            lst.append(2)
            self.n //= 2
        d = 3
        while d * d <= self.n:
            while not self.n % d:
                lst.append(d)
                self.n //= d
            d += 2
        if self.n > 1:
            lst.append(self.n)
        dct = {i: lst.count(i) for i in set(lst)}
        res = [f'{key}^{value}' if value>1 else f'{key}' for key, value in dct.items()]
        return ' * '.join(res)
