class Answer:
    def magic_dict(self, str):
        my_dict = dict()
        for letter in str:
            my_dict[letter] = sum(map(lambda x : 1 if letter in x else 0, str))
        my_dict = dict(sorted(my_dict.items(), key=lambda x: x[0]))
        return my_dict

