class Answer:
    def anagram(self, word1, word2):
        word1_d = dict()
        word2_d = dict()
        for letter1 in word1:
            word1_d[letter1] = sum(map(lambda x : 1 if letter1 in x else 0, word1))
        for letter2 in word2:
            word2_d[letter2] = sum(map(lambda x : 1 if letter2 in x else 0, word2))
        return (word1_d == word2_d)

