class Answer:
    def sort_dict(self, d, type, order):
        if type=='keywise':
            if order=='asc':
                {k: v for k, v in sorted(d.items(), key=lambda item: item[0])}
                res = {k: v for k, v in sorted(d.items(), key=lambda item: item[0])}
            else:
                res = {k: v for k, v in sorted(d.items(), key=lambda item: item[0], reverse=True)}
        else:
            if order=='asc':
                res = {k: v for k, v in sorted(d.items(), key=lambda item: item[1])}
            else:
                res = {k: v for k, v in sorted(d.items(), key=lambda item: item[1], reverse=True)}
        return res
    
