class Answer:
    def decomp(self, n):
        muls = [0] * (n + 1)
        prime = [True] * (n + 1)
        prime[0] = False
        prime[1] = False
        for i in range(2, n + 1):
            if not prime[i]:
                continue
            for j in range(i * i, n + 1, i):
                prime[j] = False
            m = n
            k = 0
            while m > 0:
                k += m // i
                m = m // i
            muls[i] = k
        res = list(filter(lambda v: v[1] > 0, [(p, i) for p, i in enumerate(muls)]))
        r = ["{}^{}".format(p, i) if i > 1 else str(p) for (p, i) in res]
        return " * ".join(r)

class Answer:
    def PureIntersection(self, arr1, arr2):
        d = {}
        res = []
        for v in arr1:
            if v not in d:
                d[v] = True
        for v in arr2:
            if v in d and d[v]:
                res.append(v)
                d[v] = False
        return res

