def fact(num):
	if num == 1 or num == 0:
		return 1
	return fact(num-1) * num

def splitit(num):
	res_dict = {}
	for i in range(2, num+1):
		if num % i == 0:
			res_dict[i] = 0
			while num % i == 0:
				res_dict[i] += 1
				num = num / i

	return list(res_dict.keys()), list(res_dict.values())

def decomp(num):
	res = ""
	new_num = fact(num)
	temp = splitit(new_num)
	keys, values = temp[0], temp[1]
	for i in range(len(keys)):
		if values[i] != 1:
			msg = f" {keys[i]}^{values[i]}"
			res += msg
		else:
			res += f" {keys[i]}"
	res = res.strip().replace(" ", " * ")
	return res

