	if num == 1 or num == 0:
		return 1
	return fact(num-1) * num


def splitit(num):
	res_dict = {}
	for i in range(2, num+1):
		if num % i == 0:
			res_dict[i] = 0
			while num % i == 0:
				res_dict[i] += 1
				num = num / i
		if num == 1:
			break
          

	return list(res_dict.keys()), list(res_dict.values())

