class Answer:
    @staticmethod
    def lim_max(num, limit):
        mins = []

        try:
            for i in num:
                if i < limit:
                    mins.append(i)
                elif min(num) > limit:
                    mins.append(-1)
                elif len(num) == 1:
                    mins.append(-1)
            res = max(mins)
        except ValueError:
            res = -1
        except TypeError:
            res = -1

        return res

