        n=100
        A = [True] * n
        lst = []
        A[0] = A[1] = False; # числам 0 и 1 сразу присваиваем значение false; (Каскадное присваивание)
        for i in range(2, n):
            if A[i]: # Четные числа - всегда истина.
                for j in range(2*i, n, i):
                    A[j] = False
        for k in range(n):
            if A[k]:
                lst.append(k)
        res=''
        for i in (lst[:-1]):
            pw=0
            k=1
            while (i**k)<n:
                pw+=math.floor(n/(i**k))
                k+=k+1
                print(pw)
            if pw>1 :
                res+=(str(i)+'^'+str(pw)+' * ')
            else:
                res+=(str(i)+' * ')       
        res+=(str(lst[-1]))   
        res
        return res

