class Answer:
    def kidsWithCandies(self, candies, extraCandies):
        m = max(candies)
        return [candie + extraCandies >= m for candie in candies]

class Counter:
    value = 0
    @classmethod
    def inc(cls):
        cls.value += 1
        return cls.value
    
    @classmethod
    def dec(cls):
        cls.value -= 1
        return cls.value

class NonDecreasingCounter(Counter):
    @classmethod
    def inc(cls):
        cls.value += 1
        return cls.value
    @classmethod
    def dec(cls):
        return cls.value

