            res = f"Деление на 0 запрещено! Ошибка: {repr(err)}."
        except TypeError as err:
            res = f"Проверьте переданный тип denom! Ошибка: {repr(err)}." 
        except Exception as err:
            res = f"Непредвиденная ошибка: {repr(err)}."

        return res

