class Answer:
    def decomp(self, n):
        prime_factors = {}
        terms = list(range(n+1))
        for i in range(2, n + 1) :
            if terms[i] != 1:
                prime_factors[terms[i]] = 1
                for j in range(i+i , n+1, i):
                    while terms[j] % i == 0:
                        prime_factors[terms[i]] += 1
                        terms[j] //= i
        return " * ".join(str(p) + (f'^{f}' if f > 1 else '') for p, f in sorted(prime_factors.items()))

