class Answer:
    def lim_max(self, nums, limit):

        if not isinstance(nums, tuple):
            raise AttributeError('Атрибут "nums" не является кортежем.')

        if not isinstance(limit, int):
            raise AttributeError('Атрибут "limit" не является целым числом.')

        # генерируем список (list comprehensions)
        lim_nums = [i for i in nums if i < limit]

        # второй раз проходим по кортежу, когда ищем максимум
        return max(lim_nums) if lim_nums else -1

