        for i in range(n+1):
            yield fibo_(i)

from functools import lru_cache
class Answer:
    def fibonacci(self, n):
        @lru_cache
        def fibo_(n):
            if i <= 1:
                return 1
            else:
                return fibo_(i-1)+fibo_(i-2)
        for i in range(n):
            yield fibo_(i)

