class Answer:  # ДЗ 7 Сортировка словаря
    @staticmethod
    def sort_dict(d, type, order):
        if type == 'keywise':
            if order == 'asc':
                return dict(sorted(d.items()))
            elif order == 'desc':
                return dict(reversed(d.items()))
        elif type == 'valuewise':
            if order == 'asc':
                sorted_dict = {}
                sorted_keys = sorted(d, key=d.get)
                for i in sorted_keys:
                    sorted_dict[i] = d[i]
                return sorted_dict
            elif order == 'desc':
                sorted_dict = {}
                sorted_keys = sorted(d, key=d.get, reverse=True)
                for i in sorted_keys:
                    sorted_dict[i] = d[i]
                return sorted_dict

