        if len(nums) <= 1:
            return nums
        mid = nums[len(nums)//2]
        scan = nums[:mid]+nums[mid+1:]
        left = [n for n in scan if n <= mid]
        right  = [n for n in scan if n > mid]
        return self.quick_sort(left) + [mid] + self.quick_sort(right)

