        self.children.append(child)
    
    def getParent(self):
        return self.parent if self.parent else self
    
    def calculateWeight(self):
        weight = 0
        
        if not self.children:
            weight = 1
            return weight
        
        for child in self.children:
            weight += child.calculateWeight()
        weight *= 2
        return weight
        
        
