class Answer:
    def decomp(self, n):
        initialMultiplier = 2
        multipliers = OrderedDict()
        
        while (n > 1):
            if n % initialMultiplier:
                n += 1
                continue
            multipliers.setdefault(n, 0)
            multipliers[n] += 1
        
        return multipliers

