class Answer:
    def getNumber(self, n):
        number = 1 
        for i in range(1, n + 1):
            number *= i
        return number
    
    def getMultipliers(self, number):
        currentMultiplier = 2
        multipliers = OrderedDict()
        while (number > 1):
            if number % currentMultiplier:
                currentMultiplier += 1
                continue
            number = number / currentMultiplier
            multipliers.setdefault(currentMultiplier, 0)
            multipliers[currentMultiplier] += 1
        return multipliers
    
    def convertMultipliersToStr(self, multipliers):
        line = ''
        for key in multipliers:
            value = multipliers[key]
            subline = str(key)
            if value > 1:
                subline = f'{subline}^{value}'
            if line:
                line = f'{line} * {subline}'
        return line
    
    def decomp(self, n):        
        number = self.getNumber(n)
        multipliers = self.getMultipliers(number)
        line = self.convertMultipliersToStr(multipliers)
        return line

