class MyPythonLexic(MyLexic):
    def __init__(self, code, problem_id, version):
        super().__init__(code, problem_id)
        self.version = version

    def strip_code(self):
        lines = self.code.split("\\n")
        lines = [line.strip() for line in lines]
        return lines
    
