class MyJavaLexic(MyLexic):
    def __init__(self, code, problem_id, platform):
        super().__init__(code, problem_id)
        self.platform = platform
        
    def strip_code(self):
        return [i.strip('{}') for i in self.code.split('\\n')]
    
