class Answer:
    def quick_sort(self, nums):
        if len(nums) <= 1:
            return nums
        mid = nums[0]
        left = [n for n in nums[1:] if n <= mid]
        right  = [n for n in nums[1:] if n > mid]
        nums = self.quick_sort(left) + [mid] + self.quick_sort(right)

class Answer:
    def update_dict(self, d, add):
        # ваше решение ниже
        res = {**d, **add}
        for i,j in d.items():
            if i in add.keys():
                res[i] = [j, res[i]]

        return res
    
