class Answer:
    def list_cond(self, start, stop, n_div):
        if n_div == 0:
            return -1
        offset = 0 if (start % n_div == 0) else (n_div - abs(start) % n_div)
        step = 1 if start <= stop else -1
        res = list(range(start + offset * step, stop + 1 * step, n_div * step))
        return res

