class Answer:
    def gcd(self, a, b):
        a_d = []
        b_d = []
        c = []
        for i in range(1, a + 1):
            if a % i == 0:
                a_d.append(i)
        for j in range(1, b + 1):
            if b % j == 0:
                b_d.append(j)
        for i in a_d:
            for j in b_d:
                if i == j:
                    c.append(i)
                    break
        return c[-1]

