class Answer:
    def decomp(self, n):
        d = dict()
        for i in range(2, n+1):
            k = 2
            while i > 1:
                while i % k == 0:
                    d.setdefault(k,0)
                    d[k] += 1
                    i //= k
                k += 1
        lis = ['1']
        for k in sorted( d.keys() ):
            lis.append(f'{k}^{d[k]}')
        res = ' * '.join(lis)
        return res

