import numpy as np


class Answer:
    @staticmethod
    def CalsStatistics(arr, type):
        res = np.array(arr)
        if type == 'colwise':
            mean = np.mean(res, axis=0)
            var = np.var(res, axis=0)
            std = np.std(res, axis=0)
            sum = np.sum(res, axis=0)
        elif type == 'rowwise':
            mean = np.mean(res, axis=1)
            var = np.var(res, axis=1)
            std = np.std(res, axis=1)
            sum = np.sum(res, axis=1)

        return mean, var, std, sum

