class Answer:
    def decomp(self, n):
        factorial = 1
        for i in range(n, 0, -1):
            factorial = factorial * i
        
        simple_numbers = []
        for i in range(2, factorial+1):
            if self.is_simple(i):
                simple_numbers.append(i)
                
        counts = [0] * simple_numbers[-1]
        while(factorial > 1):
            for x in simple_numbers:
                if factorial % x == 0:
                    factorial = factorial / x
                    counts[x] += 1
                    break
        res = ""
        for i in range(len(counts)):
            if counts[i] != 0:
                res += str(i) + ("^" + str(counts[i]) + ' * ' if (counts[i] != 1) else ' * ')
        
        res = res[:len(res)-3]
        return res
      
    def is_simple(self, n: int) -> bool:
        for i in range(2, n):
            if n % i == 0:
                return False
        return True

