class Answer:
    def decomp(self, n):
        res = ""
        factorial = 1
        for i in range(n, 0, -1):
            factorial = factorial * i
                
        num = 0
        for x in range(2, factorial):
            if self.is_simple(x):
                while (factorial % x == 0):
                    factorial = factorial / x
                    num += 1
                res += str(x) + ("^" + str(num)) + ' * ' if (num != 1) else str(x) + ' * '
                num = 0
                
            if (factorial == 1):
                break

        res = res[:len(res)-3]
        return res
      
    def is_simple(self, n: int) -> bool:
        for i in range(2, n):
            if n % i == 0:
                return False
        return True
    
