class Answer:
    def list_add_num(self, ref_list, start, stop, num):
        # напишите свой код ниже
        a = start
        b = stop
        c = []
        if a >= len(ref_list) or b >= len(ref_list):
            return -1
        if a <= b:
            for i in range(a, b + 1, 1):
                c.append(i)
        if a > b:
            for j in range(a, b - 1, -1):
                c.append(j)
        for h in range(len(ref_list)):
            if h in c:
                ref_list[h] += num
        return ref_list

