from operator import itemgetter
class Answer:
    def sort_dict(self, d, type, order):
        # ваше решение ниже
        if type == 'keywise' and order == 'desc':
            d = dict(sorted(d.items(), reverse = True, key=lambda x: x[0]))
        if type == 'valuewise' and order == 'desc':
            d = dict(sorted(d.items(), reverse = True, key=lambda x: x[1]) )
        elif type == 'keywise' and order == 'asc':
            d = dict(sorted(d.items(), key=lambda x: x[0]))
        elif type == 'valuewise' and order == 'asc':
            d = dict(sorted(d.items(), key=lambda x: x[1]) )  
        return d

class Answer:
    def bubble_sort(self, nums):
        for i in range(len(nums)):
            for id in range(1, len(nums)):
                if nums[id] < nums[id-1]:
                    nums[id], nums[id-1] = nums[id-1], nums[id] 
        return nums

