class Answer:
    def segment(self, num, scale):
        res = ()
        count = 0
        while scale[count] < num:
                count += 1
        if scale[count] == num:
            res = (num, num)
        elif scale[count] > num:
            res = (scale[count - 1], scale[count])
        return res


