class Answer:
    def segment(self, num, scale):

        # для наглядности отступы не соответствуют требованиям PEP8

        n_left =  [i for i in scale if i <= num     ]

        n_right = [i for i in scale if      num <= i]

        return (max(n_left), min(n_right))

