class Answer:
    def CountSpecialProblems(self, n, k, arr):
        count = 0
        pages = 1
        for i in arr:
            for a in range(1, i+1):
                #print(pages, ' ', a)
                if a == pages:
                    count+=1
                if a % k == 0:
                    pages+=1
            if i % k != 0:
                pages+=1
        return count

